__CR('t:arduino',[{"t":"아두이노 첫걸음","l":[{"t":"아두이노란?","q":[{"t":"choice","k":"언어","q":"아두이노 프로그래밍 언어는 무엇을 기반으로 하나요?","o":["Python","C/C++","JavaScript","SQL"],"a":1,"ex":"아두이노 스케치는 C/C++ 문법을 사용합니다."},{"t":"choice","k":"구조","q":"아두이노 코드에서 처음에 딱 한 번만 실행되는 함수는?","o":["setup()","loop()","main()","start()"],"a":0,"ex":"setup() 에서 초기 설정(핀 모드 등)을 합니다."},{"t":"choice","k":"개념","q":"아두이노는 기본적으로 무엇인가요?","o":["전자 회로를 제어하는 마이크로컨트롤러 보드","웹 브라우저","데이터베이스","운영체제"],"a":0,"ex":"아두이노는 센서·모터·LED 등을 제어하는 작은 컴퓨터 보드입니다."},{"t":"choice","k":"구조","q":"setup() 이후 계속 반복해서 실행되는 함수는?","o":["setup()","loop()","repeat()","again()"],"a":1,"ex":"loop() 안의 코드가 무한 반복됩니다."}],"th":{"sum":"아두이노는 작은 컴퓨터가 달린 보드다. 전기 신호를 읽고 내보내서 **바깥 세상과 이어지는** 것이 목적이다.","body":[{"h":"컴퓨터와 다른 점","t":"화면도 키보드도 없다. 대신 핀이라는 금속 다리가 있어서 전선을 꽂는다. 프로그램은 컴퓨터에서 작성해 USB 로 보드에 옮겨 넣는다. 옮기고 나면 컴퓨터 없이 전원만 있으면 혼자 돈다."},{"h":"setup 과 loop","t":"`setup()` 은 전원이 켜질 때 **한 번만** 돈다. 준비 작업을 여기에 적는다. `loop()` 는 그 뒤로 **끝없이 반복**된다. 준비 작업을 실수로 loop 에 적으면 매번 다시 준비하느라 이상하게 동작한다."},{"h":"코드가 맞아도 안 될 수 있다","t":"아두이노는 배선이 함께 맞아야 동작한다. 코드가 완벽해도 전선 하나가 빠져 있으면 아무 일도 일어나지 않는다. '안 되면 코드보다 배선을 먼저 본다' 가 기본이다."}],"code":{"c":"void setup() {\n    pinMode(13, OUTPUT);   // 한 번만\n}\n\nvoid loop() {\n    digitalWrite(13, HIGH);  // 끝없이 반복\n}","cap":"setup 은 한 번, loop 는 계속"},"key":["핀으로 바깥 세상과 잇는다","`setup` 은 한 번, `loop` 는 반복","안 되면 배선을 먼저 본다"]}},{"t":"핀과 제어","q":[{"t":"choice","k":"함수","q":"핀을 입력(INPUT) 또는 출력(OUTPUT)으로 설정하는 함수는?","o":["pinMode()","setPin()","digitalWrite()","begin()"],"a":0,"ex":"pinMode(13, OUTPUT) 처럼 핀의 역할을 정합니다."},{"t":"choice","k":"함수","q":"프로그램을 잠시(밀리초 단위) 멈추게 하는 함수는?","o":["stop()","wait()","delay()","sleep()"],"a":2,"ex":"delay(1000) 은 1초 동안 멈춥니다."},{"t":"choice","k":"함수","q":"디지털 핀에 HIGH/LOW(켜기/끄기) 를 출력하는 함수는?","o":["analogRead()","digitalWrite()","delay()","print()"],"a":1,"ex":"digitalWrite(13, HIGH) 로 LED 를 켭니다."},{"t":"choice","k":"제어","q":"LED 를 켜려면 핀에 어떤 값을 줘야 하나요?","o":["HIGH","LOW","OFF","0"],"a":0,"ex":"HIGH 는 전압을 걸어 켜고, LOW 는 끕니다."}],"th":{"sum":"핀은 전기가 드나드는 문이다. 각 핀을 '내보내는 문' 으로 쓸지 '받아들이는 문' 으로 쓸지 먼저 정해 준다.","body":[{"h":"먼저 방향을 정한다","t":"`pinMode(13, OUTPUT)` 은 13번 핀을 내보내기용으로 쓰겠다는 선언이다. 읽으려면 `INPUT` 이다. 이걸 빠뜨리면 값이 제대로 나가지도 들어오지도 않는다 — `setup()` 에서 한 번 정해 둔다."},{"h":"디지털은 둘, 아날로그는 여럿","t":"`digitalWrite` 는 켬(HIGH)과 끔(LOW) 둘 중 하나만 보낸다. `analogRead` 는 0~5V 사이의 값을 0~1023 숫자로 읽는다. 밝기나 온도처럼 정도가 있는 값은 아날로그 쪽이다."},{"h":"delay 는 모든 것을 멈춘다","t":"`delay(1000)` 은 1초 동안 **아무것도 못 하게** 만든다. 그동안 버튼을 눌러도 반응하지 않는다. 여러 일을 함께 하려면 `millis()` 로 시각을 재서 '지날 때가 됐는지' 확인하는 방식으로 바꾼다."}],"code":{"c":"void setup() {\n    pinMode(13, OUTPUT);\n    pinMode(2, INPUT);\n}\n\nvoid loop() {\n    if (digitalRead(2) == HIGH)\n        digitalWrite(13, HIGH);\n}","cap":"방향을 먼저 정하고 쓴다"},"key":["`pinMode` 로 방향을 먼저 정한다","디지털은 켬·끔, 아날로그는 0~1023","`delay` 는 그동안 아무것도 못 한다"]}},{"t":"직접 이어 보기 — LED 를 켜는 회로","th":{"sum":"LED 는 **저항 없이 물리면 탄다.** 그리고 방향이 있어서 거꾸로 꽂으면 아예 안 켜진다.","body":[{"h":"왜 저항이 필요한가","t":"LED 는 전압이 조금만 넘어도 전류가 급격히 늘어난다. 5V 를 그대로 물리면 견딜 수 있는 전류를 훌쩍 넘겨 순식간에 망가진다. 220Ω 정도를 **직렬로** 끼워 전류를 제한한다 — LED 옆이 아니라 전류가 지나가는 길목에 있어야 한다."},{"h":"방향이 있다","t":"긴 다리(애노드, +)가 전원 쪽, 짧은 다리(캐소드, −)가 GND 쪽이다. 거꾸로 꽂으면 전류가 흐르지 않아 그냥 안 켜진다 — 고장이 아니라서 더 헷갈린다."},{"h":"회로는 돌아와야 한다","t":"핀에서 나간 전류가 GND 로 **돌아와야** 회로가 완성된다. GND 를 빼먹으면 아무 일도 일어나지 않는다. 아두이노에서 가장 흔한 '왜 안 되지' 의 정체다."}],"code":{"c":"void setup() { pinMode(13, OUTPUT); }\nvoid loop() { digitalWrite(13, HIGH); }\n// 코드가 맞아도 배선이 틀리면 안 켜진다","cap":"코드보다 배선이 먼저다"},"key":["LED 앞에는 저항을 직렬로","긴 다리가 +, 짧은 다리가 −","GND 로 돌아와야 회로가 닫힌다"]},"q":[{"k":"LED 켜기 — 저항을 거쳐서","cat":"internals","q":"13번 핀으로 LED 를 켜는 회로를 만드세요. <b>반드시 220Ω 저항을 거쳐야</b> 하고, LED 의 짧은 다리는 GND 로 가야 합니다.","ex":"저항은 LED 옆에 놓는 게 아니라 전류가 지나가는 길목에 끼워야 합니다. D13 → 저항 → LED(+) → LED(−) → GND 순서로 한 줄이 되어야 해요. 저항을 빼고 바로 이으면 LED 가 탑니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["D13","D2","5V","GND"]},{"id":"r","label":"220Ω 저항","pins":["1","2"]},{"id":"led","label":"LED","pins":["+","−"]}],"checks":[{"d":"D13 이 LED 의 + 로 이어진다","link":["uno.D13","led.+"]},{"d":"그 사이에 220Ω 저항이 끼어 있다","link":["uno.D13","led.+"],"through":"r"},{"d":"LED 의 − 가 GND 로 간다","link":["led.−","uno.GND"]},{"d":"5V 와 GND 가 바로 붙어 있지 않다","apart":["uno.5V","uno.GND"],"wires":true}],"start":[],"sol":[["uno.D13","r.1"],["r.2","led.+"],["led.−","uno.GND"]]},{"k":"합선 고치기","cat":"internals","q":"누군가 5V 와 GND 를 <b>바로 이어</b> 놓았습니다. 이 선을 지우고, LED 가 <b>5V 로 상시 점등</b>되도록 저항을 거쳐 다시 이으세요.","ex":"5V 와 GND 를 바로 이으면 아무것도 막지 않는 길이 생겨 큰 전류가 흐릅니다(합선). 보드가 보호 회로로 버티더라도 절대 만들면 안 되는 배선이에요. 먼저 그 선을 지운 뒤 저항과 LED 를 사이에 넣으세요.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["D13","5V","GND"]},{"id":"r","label":"330Ω 저항","pins":["1","2"]},{"id":"led","label":"LED","pins":["+","−"]}],"checks":[{"d":"5V 와 GND 를 바로 잇는 선이 없다","apart":["uno.5V","uno.GND"],"wires":true},{"d":"5V 가 LED 의 + 로 이어진다","link":["uno.5V","led.+"]},{"d":"그 사이에 저항이 끼어 있다","link":["uno.5V","led.+"],"through":"r"},{"d":"LED 의 − 가 GND 로 간다","link":["led.−","uno.GND"]}],"start":[["uno.5V","uno.GND"]],"sol":[["uno.5V","r.1"],["r.2","led.+"],["led.−","uno.GND"]]}]}]},{"t":"입력과 통신","l":[{"t":"센서 읽기","q":[{"t":"choice","k":"함수","q":"온도·빛 같은 아날로그 센서 값을 읽는 함수는?","o":["analogRead()","digitalWrite()","pinMode()","delay()"],"a":0,"ex":"analogRead(A0) 은 0~1023 범위 값을 읽습니다."},{"t":"choice","k":"개념","q":"analogRead() 가 돌려주는 값의 범위는? (10비트)","o":["0~1","0~255","0~1023","0~65535"],"a":2,"ex":"10비트라 0부터 1023까지입니다."},{"t":"choice","k":"함수","q":"버튼처럼 켜짐/꺼짐만 있는 디지털 입력을 읽는 함수는?","o":["digitalRead()","analogWrite()","print()","loop()"],"a":0,"ex":"digitalRead(핀) 은 HIGH 또는 LOW 를 돌려줍니다."},{"t":"choice","k":"부품","q":"빛의 밝기를 감지하는 대표적인 센서는?","o":["조도 센서(CDS)","LED","저항","버저"],"a":0,"ex":"조도(빛) 센서로 밝기를 읽어 제어할 수 있습니다."}],"th":{"sum":"센서 값은 아날로그는 `analogRead`(0~1023), 디지털은 `digitalRead`로 읽고, PC와의 통신·디버깅은 `Serial`로 하며 코드를 보드로 옮기는 과정을 **업로드**라 한다.","body":[{"h":"센서 읽기","t":"온도·빛처럼 연속적으로 변하는 아날로그 센서 값은 analogRead(pin) 함수로 읽는다. 아두이노의 ADC는 10비트라서 반환값 범위는 0~1023이다. 버튼처럼 켜짐/꺼짐만 있는 디지털 입력은 digitalRead(pin)로 읽어 HIGH 또는 LOW를 얻는다. 빛의 밝기를 감지하는 대표적 센서는 조도 센서(광센서, CDS/포토레지스터)다."},{"h":"통신과 업로드","t":"아두이노가 PC와 값을 주고받거나 디버깅 메시지를 출력할 때 쓰는 것이 시리얼(Serial) 통신이다. Serial.begin(speed) 함수로 통신을 시작하며 속도(보드레이트, 예: 9600)를 정한다. 작성한 코드를 컴파일해 아두이노 보드로 옮겨 실제로 동작시키는 과정을 업로드(upload)라 한다."}],"code":{"c":"void setup() {\n  Serial.begin(9600);        // 시리얼 통신 시작\n}\nvoid loop() {\n  int v = analogRead(A0);    // 0~1023\n  Serial.println(v);         // PC로 값 출력\n  delay(500);\n}","cap":"아날로그 센서 값을 읽어 시리얼로 출력"},"key":["아날로그 = analogRead(0~1023, 10비트), 디지털 = digitalRead","빛 감지 센서 = 조도 센서(CDS)","PC 통신·디버깅 = Serial, 시작 = Serial.begin(속도), 코드 옮기기 = 업로드"]}},{"t":"통신과 업로드","q":[{"t":"choice","k":"통신","q":"아두이노가 PC 와 값을 주고받거나 디버깅 출력에 쓰는 것은?","o":["Serial","WiFi만","HDMI","USB 마우스"],"a":0,"ex":"Serial.print() 로 PC 화면에 값을 출력해 확인합니다."},{"t":"choice","k":"함수","q":"Serial 통신을 시작하며 속도를 정하는 함수는?","o":["Serial.begin()","Serial.on()","Serial.start()","Serial.open()"],"a":0,"ex":"setup() 에서 Serial.begin(9600) 처럼 시작합니다."},{"t":"choice","k":"과정","q":"작성한 코드를 아두이노 보드로 옮기는 과정을 뭐라 하나요?","o":["업로드","다운로드","컴파일만","백업"],"a":0,"ex":"아두이노 IDE 에서 업로드하면 보드에서 실행됩니다."},{"t":"choice","k":"개념","q":"소리를 내는 데 쓰는 부품은?","o":["버저(피에조)","저항","점퍼선","브레드보드"],"a":0,"ex":"버저로 소리(알람·멜로디)를 낼 수 있습니다."}],"th":{"sum":"센서 값은 아날로그는 `analogRead`(0~1023), 디지털은 `digitalRead`로 읽고, PC와의 통신·디버깅은 `Serial`로 하며 코드를 보드로 옮기는 과정을 **업로드**라 한다.","body":[{"h":"센서 읽기","t":"온도·빛처럼 연속적으로 변하는 아날로그 센서 값은 analogRead(pin) 함수로 읽는다. 아두이노의 ADC는 10비트라서 반환값 범위는 0~1023이다. 버튼처럼 켜짐/꺼짐만 있는 디지털 입력은 digitalRead(pin)로 읽어 HIGH 또는 LOW를 얻는다. 빛의 밝기를 감지하는 대표적 센서는 조도 센서(광센서, CDS/포토레지스터)다."},{"h":"통신과 업로드","t":"아두이노가 PC와 값을 주고받거나 디버깅 메시지를 출력할 때 쓰는 것이 시리얼(Serial) 통신이다. Serial.begin(speed) 함수로 통신을 시작하며 속도(보드레이트, 예: 9600)를 정한다. 작성한 코드를 컴파일해 아두이노 보드로 옮겨 실제로 동작시키는 과정을 업로드(upload)라 한다."}],"code":{"c":"void setup() {\n  Serial.begin(9600);        // 시리얼 통신 시작\n}\nvoid loop() {\n  int v = analogRead(A0);    // 0~1023\n  Serial.println(v);         // PC로 값 출력\n  delay(500);\n}","cap":"아날로그 센서 값을 읽어 시리얼로 출력"},"key":["아날로그 = analogRead(0~1023, 10비트), 디지털 = digitalRead","빛 감지 센서 = 조도 센서(CDS)","PC 통신·디버깅 = Serial, 시작 = Serial.begin(속도), 코드 옮기기 = 업로드"]}},{"t":"직접 이어 보기 — 버튼 읽기","th":{"sum":"입력 핀은 아무것도 연결되지 않으면 **값이 떠다닌다**(플로팅). 0도 1도 아닌 상태라 읽을 때마다 달라진다.","body":[{"h":"풀다운·풀업 저항","t":"버튼을 누르지 않았을 때 핀을 확실한 값으로 붙잡아 두는 저항이다. 10kΩ 을 GND 로 걸면 평소 LOW(풀다운), 5V 로 걸면 평소 HIGH(풀업)다. 이게 없으면 손을 가까이 대는 것만으로도 값이 바뀐다."},{"h":"내장 풀업","t":"`pinMode(2, INPUT_PULLUP)` 을 쓰면 보드 안의 저항이 붙어 배선이 하나 줄어든다. 대신 **눌렀을 때 LOW** 가 되어 논리가 뒤집힌다 — 이걸 모르면 버튼이 거꾸로 동작한다."}],"code":{"c":"pinMode(2, INPUT_PULLUP);\nif (digitalRead(2) == LOW) { /* 눌림 */ }\n// 내장 풀업은 눌렀을 때 LOW 다","cap":"안 눌렀을 때의 값을 정해 둬야 한다"},"key":["아무것도 안 걸면 값이 떠다닌다","풀다운은 평소 LOW, 풀업은 평소 HIGH","내장 풀업은 논리가 뒤집힌다"]},"q":[{"k":"버튼 + 풀다운 저항","cat":"internals","q":"2번 핀으로 버튼을 읽는 회로를 만드세요. 버튼을 누르면 <b>5V 가 2번 핀에</b> 닿고, 안 눌렀을 때는 <b>10kΩ 저항을 거쳐 GND</b> 로 붙잡혀 있어야 합니다.","ex":"풀다운 저항이 없으면 버튼을 안 눌렀을 때 2번 핀이 아무 데도 연결되지 않아 값이 떠다닙니다. 저항을 GND 로 걸어 평소 LOW 로 붙잡아 둬야 해요. 저항 없이 GND 에 바로 이으면 버튼을 눌렀을 때 5V 와 GND 가 합선됩니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["D2","5V","GND"]},{"id":"btn","label":"버튼","pins":["1","2"],"noInternal":true},{"id":"rd","label":"10kΩ 풀다운","pins":["1","2"]}],"checks":[{"d":"버튼 한쪽이 5V 에 붙는다","link":["btn.1","uno.5V"]},{"d":"버튼 다른 쪽이 2번 핀으로 간다","link":["btn.2","uno.D2"]},{"d":"2번 핀이 저항을 거쳐 GND 로 붙잡힌다","link":["uno.D2","uno.GND"],"through":"rd"},{"d":"5V 와 GND 가 바로 붙어 있지 않다","apart":["uno.5V","uno.GND"],"wires":true}],"start":[],"sol":[["btn.1","uno.5V"],["btn.2","uno.D2"],["uno.D2","rd.1"],["rd.2","uno.GND"]]},{"k":"내장 풀업으로 배선 줄이기","cat":"internals","q":"<code>INPUT_PULLUP</code> 을 쓰면 외부 저항이 필요 없습니다. 버튼 한쪽을 <b>3번 핀</b>에, 다른 쪽을 <b>GND</b> 에 이으세요. 5V 는 쓰지 않습니다.","ex":"내장 풀업은 보드 안에서 핀을 5V 쪽으로 붙잡아 둡니다. 그래서 버튼은 GND 로만 내리면 되고, 누르면 LOW 가 돼요 — 논리가 뒤집히는 것을 코드에서 감안해야 합니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["D3","5V","GND"]},{"id":"btn","label":"버튼","pins":["1","2"],"noInternal":true}],"checks":[{"d":"버튼 한쪽이 3번 핀에 붙는다","link":["btn.1","uno.D3"]},{"d":"버튼 다른 쪽이 GND 로 간다","link":["btn.2","uno.GND"]},{"d":"5V 는 쓰지 않는다","apart":["uno.5V","uno.D3"],"wires":true},{"d":"5V 와 GND 가 바로 붙어 있지 않다","apart":["uno.5V","uno.GND"],"wires":true}],"start":[],"sol":[["btn.1","uno.D3"],["btn.2","uno.GND"]]}]}]},{"t":"디지털·아날로그 입출력과 PWM 듀티 제어","l":[{"t":"핀 모드와 디지털 입력의 함정","q":[{"t":"choice","k":"uno-pinmode-output-basic","q":"Arduino Uno에서 13번 핀에 LED를 연결해 켜고 끄려 합니다. setup()에 넣어야 할 코드로 가장 알맞은 것은?","ex":"핀에서 전압을 내보내려면 pinMode로 OUTPUT을 지정해야 하며, INPUT은 읽기 전용 설정입니다.\n💡 개념: pinMode는 핀 방향(입력/출력)을 정하고, digitalWrite는 그 출력 핀에 HIGH/LOW를 씁니다.\n🛠 실무: 출력 지정을 빼먹으면 LED가 아주 흐리게만 켜지는 이상 증상이 나와 배선을 의심하다 시간을 버리기 쉽습니다.","o":["pinMode(13, INPUT);","pinMode(13, OUTPUT);","analogWrite(13, OUTPUT);","digitalRead(13, OUTPUT);"],"a":1},{"t":"choice","k":"uno-input-pullup-press-level","q":"버튼 한쪽을 Uno의 4번 핀, 반대쪽을 GND에 연결하고 pinMode(4, INPUT_PULLUP)을 했습니다. 버튼을 눌렀을 때 digitalRead(4)의 값은?","ex":"내부 풀업이 평소 핀을 5V로 당겨 HIGH이고, 버튼을 누르면 핀이 GND에 연결되어 LOW로 떨어집니다.\n💡 개념: INPUT_PULLUP은 눌림이 LOW인 액티브 로우 논리이므로 조건문을 == LOW로 써야 합니다.\n🛠 실무: 외부 풀업 저항을 따로 달지 않아도 되어 배선이 줄고, 플로팅 오동작도 함께 사라집니다.","o":["1023","HIGH","LOW","누를 때마다 무작위"],"a":2},{"t":"choice","k":"uno-pullup-resistor-need","q":"INPUT_PULLUP 대신 pinMode(4, INPUT)만 쓰면서 버튼을 GND에 연결한 회로를 안정적으로 만들려면 추가로 필요한 것은?","ex":"내부 풀업을 쓰지 않는다면 핀과 5V 사이에 외부 풀업 저항을 달아 평소 HIGH를 만들어 줘야 합니다.\n💡 개념: INPUT_PULLUP은 ATmega328P 칩 안에 있는 풀업 저항을 소프트웨어로 켜는 것과 같습니다.\n🛠 실무: 긴 배선이나 노이즈가 심한 환경에서는 값이 작은 외부 풀업이 내부 풀업보다 더 안정적입니다.","o":["PWM 가능 핀으로 버튼을 옮긴다","핀과 5V 사이에 외부 풀업 저항을 단다","analogRead로 버튼을 읽는다","Serial.begin의 보율을 115200으로 올린다"],"a":1},{"t":"choice","k":"uno-floating-input-cause","q":"Uno의 2번 핀을 pinMode(2, INPUT)으로 두고 아무것도 연결하지 않은 채 digitalRead(2)를 반복하면 값이 HIGH와 LOW를 마구 오갑니다. 원인은?","ex":"연결이 없는 입력 핀은 주변 노이즈에 따라 전압이 떠다니는 플로팅 상태가 되어 값이 불안정합니다.\n💡 개념: 디지털 입력은 반드시 HIGH나 LOW 어느 한쪽으로 확정시켜 줄 풀업 또는 풀다운이 필요합니다.\n🛠 실무: 스위치 입력이 가끔 저절로 눌린 것처럼 동작하면 가장 먼저 플로팅을 의심하세요.","o":["핀이 어디에도 연결되지 않아 전압이 떠 있는 플로팅 상태이기 때문","digitalRead는 원래 난수를 반환하도록 설계되었기 때문","2번 핀이 PWM 전용 핀이라 디지털 읽기가 불가능하기 때문","10비트 ADC의 양자화 오차가 디지털 입력에 섞이기 때문"],"a":0},{"t":"input","k":"uno-pullup-mode-name","q":"Arduino Uno에서 내부 풀업 저항을 켜서 플로팅을 막는 pinMode의 세 번째 인자(모드) 이름을 그대로 적어보세요. (예: 영문 대문자 또는 소문자)","ex":"정답은 INPUT_PULLUP이며 pinMode(pin, INPUT_PULLUP) 형태로 씁니다.\n💡 개념: 이 모드를 쓰면 평소 HIGH, 버튼을 누르면 LOW로 읽히는 액티브 로우 구조가 됩니다.\n🛠 실무: 버튼 입력 코드는 대부분 INPUT_PULLUP을 기본으로 쓰고 회로에서 저항을 생략합니다.","a":["INPUT_PULLUP","input_pullup","INPUT PULLUP","인풋 풀업"]}],"th":{"sum":"Arduino Uno(ATmega328P)의 핀은 디지털 HIGH/LOW 입출력과 10비트 ADC 입력, 8비트 PWM 출력을 담당합니다. PWM은 평균 전압을 흉내 낼 뿐 진짜 아날로그 출력(DAC)이 아니라는 점이 핵심입니다.","body":[{"h":"pinMode와 디지털 입출력","t":"Arduino Uno에서 핀은 pinMode(pin, OUTPUT)으로 출력, INPUT 또는 INPUT_PULLUP으로 입력이 됩니다. 출력 핀은 digitalWrite(pin, HIGH/LOW)로 5V 또는 0V를 내보냅니다. 입력 핀은 digitalRead(pin)으로 HIGH(1) 또는 LOW(0)만 읽습니다. 즉 디지털 입출력에는 중간값이 없습니다."},{"h":"플로팅 입력과 INPUT_PULLUP","t":"아무 데도 연결되지 않은 입력 핀은 전압이 떠다니며(floating) HIGH와 LOW를 제멋대로 오갑니다. pinMode(pin, INPUT_PULLUP)을 쓰면 ATmega328P 내부 풀업 저항이 켜져 평소 핀이 5V 쪽으로 당겨져 HIGH로 고정됩니다. 버튼의 반대편을 GND에 연결했다면 버튼을 눌렀을 때 핀이 GND로 떨어져 LOW로 읽힙니다. 그래서 INPUT_PULLUP 버튼 코드는 눌림을 LOW로 판정합니다."},{"h":"analogRead는 10비트 ADC","t":"Uno의 A0~A5는 10비트 ADC에 연결되어 analogRead()가 0~1023의 정수를 돌려줍니다. 기준 전압이 5V일 때 한 단계는 약 5V / 1024 = 약 4.9mV입니다. 전압으로 바꾸려면 value * 5.0 / 1023.0 같은 식을 씁니다. analogRead는 값을 읽는 입력 전용이며 출력과는 무관합니다."},{"h":"analogWrite는 8비트 PWM 듀티","t":"analogWrite(pin, 0~255)는 8비트 듀티비를 지정해 핀을 아주 빠르게 켜고 끕니다. 128이면 대략 50% 시간만 HIGH라 LED가 절반 밝기로 보이고 평균 전압이 약 2.5V처럼 측정됩니다. 하지만 순간 전압은 여전히 0V 아니면 5V이므로 진짜 아날로그 전압을 만드는 DAC와 다릅니다. Uno에서 PWM이 가능한 핀은 3, 5, 6, 9, 10, 11뿐이고 나머지 디지털 핀에 analogWrite를 하면 의도한 밝기 조절이 되지 않습니다."}],"code":{"c":"const int BTN = 2;   // 버튼: 한쪽은 핀2, 반대쪽은 GND\nconst int LED = 9;   // Uno PWM 가능 핀\n\nvoid setup() {\n  pinMode(BTN, INPUT_PULLUP); // 내부 풀업 ON, 평소 HIGH\n  pinMode(LED, OUTPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  int raw = analogRead(A0);          // 0~1023 (10비트)\n  int duty = map(raw, 0, 1023, 0, 255); // 0~255 (8비트 PWM)\n  if (digitalRead(BTN) == LOW) duty = 0; // 눌리면 LOW\n  analogWrite(LED, duty);\n  Serial.println(raw * 5.0 / 1023.0); // 전압 환산\n}","cap":"가변저항 값을 10비트로 읽어 8비트 PWM 듀티로 바꿔 LED 밝기를 조절하고, INPUT_PULLUP 버튼으로 끕니다."},"key":["analogRead는 10비트라 0~1023을 반환하고 5V 기준 한 단계는 약 4.9mV다","analogWrite는 0~255의 8비트 듀티이며 PWM은 평균 전압일 뿐 DAC가 아니다","Uno의 PWM 핀은 3, 5, 6, 9, 10, 11로 제한된다","INPUT_PULLUP은 플로팅을 막고 GND에 연결된 버튼이 눌릴 때 LOW로 읽히게 한다"]}},{"t":"analogRead 10비트와 전압 분해능","q":[{"t":"choice","k":"uno-analogread-range","q":"Arduino Uno에서 analogRead(A0)가 반환할 수 있는 값의 범위는?","ex":"Uno의 ADC는 10비트라 2의 10승인 1024단계, 즉 0부터 1023까지의 정수를 반환합니다.\n💡 개념: 0~255는 analogWrite의 8비트 듀티 범위이고, 0~4095는 12비트 ADC를 가진 다른 보드의 값입니다.\n🛠 실무: 보드를 ESP32 등으로 옮기면 ADC 비트 수가 달라지므로 1023을 상수로 박아둔 코드는 반드시 다시 확인해야 합니다.","o":["0 ~ 255","0 ~ 4095","0 ~ 1023","0 ~ 65535"],"a":2},{"t":"choice","k":"uno-analogread-digital-pin","q":"Uno에서 디지털 핀 7에 연결된 스위치의 온오프 상태를 읽으려 합니다. 가장 알맞은 함수는?","ex":"온오프 두 상태만 필요하므로 HIGH/LOW를 돌려주는 digitalRead가 알맞습니다.\n💡 개념: analogRead는 A0~A5의 아날로그 입력 핀에서 연속적인 전압을 0~1023으로 읽을 때 씁니다.\n🛠 실무: 아날로그 핀 A0~A5도 digitalRead로 디지털 입력처럼 쓸 수 있어 핀이 모자랄 때 유용합니다.","o":["analogWrite(7, 255)","analogRead(7)","pinMode(7, HIGH)","digitalRead(7)"],"a":3},{"t":"choice","k":"uno-adc-step-voltage","q":"기준 전압이 5V인 Uno에서 10비트 analogRead 한 단계(LSB)에 해당하는 전압은 대략 얼마입니까?","ex":"5V를 1024단계로 나누면 한 단계는 약 0.00488V, 즉 약 4.9mV입니다.\n💡 개념: 약 19.6mV는 5V를 256단계로 나눈 8비트 분해능이라 Uno의 ADC와 다릅니다.\n🛠 실무: 더 미세한 전압을 봐야 하면 analogReference로 기준 전압을 1.1V 내부 기준으로 낮추거나 외부 ADC를 씁니다.","o":["약 4.9mV","약 19.6mV","약 0.5V","약 5V"],"a":0},{"t":"choice","k":"uno-adc-to-voltage-calc","q":"5V 기준 Uno에서 analogRead(A0)가 512를 반환했습니다. 입력 전압은 대략 얼마입니까?","ex":"512는 0~1023 범위의 거의 정확한 중간이므로 5V의 절반인 약 2.5V입니다.\n💡 개념: 전압 = 값 * 5.0 / 1023.0 식으로 환산하며 512는 약 2.50V가 나옵니다.\n🛠 실무: 전압 분배 회로로 5V가 넘는 신호를 낮춰 넣을 때는 분배비를 곱해 원래 전압으로 되돌려야 합니다.","o":["약 0.5V","약 2.5V","약 3.3V","약 5.0V"],"a":1},{"t":"choice","k":"uno-adc-resolution-meaning","q":"같은 5V 범위를 10비트 ADC 대신 8비트 ADC로 읽으면 생기는 변화로 옳은 것은?","ex":"비트 수는 전압 범위가 아니라 그 범위를 몇 단계로 쪼개는지를 결정하므로 256단계로 거칠어집니다.\n💡 개념: 분해능이 낮아지면 작은 전압 변화가 같은 숫자로 뭉뚱그려져 감지되지 않습니다.\n🛠 실무: 미세한 센서 변화를 봐야 하는 계측 프로젝트에서는 ADC 비트 수가 곧 성능 한계가 됩니다.","o":["측정 가능한 최대 전압이 5V에서 2.5V로 줄어든다","단계 수가 1024에서 256으로 줄어 한 단계당 전압 폭이 커진다","샘플 값이 0~1023에서 0~2047로 늘어난다","전압을 아예 읽지 못하고 HIGH/LOW만 나온다"],"a":1}],"th":{"sum":"Arduino Uno(ATmega328P)의 핀은 디지털 HIGH/LOW 입출력과 10비트 ADC 입력, 8비트 PWM 출력을 담당합니다. PWM은 평균 전압을 흉내 낼 뿐 진짜 아날로그 출력(DAC)이 아니라는 점이 핵심입니다.","body":[{"h":"pinMode와 디지털 입출력","t":"Arduino Uno에서 핀은 pinMode(pin, OUTPUT)으로 출력, INPUT 또는 INPUT_PULLUP으로 입력이 됩니다. 출력 핀은 digitalWrite(pin, HIGH/LOW)로 5V 또는 0V를 내보냅니다. 입력 핀은 digitalRead(pin)으로 HIGH(1) 또는 LOW(0)만 읽습니다. 즉 디지털 입출력에는 중간값이 없습니다."},{"h":"플로팅 입력과 INPUT_PULLUP","t":"아무 데도 연결되지 않은 입력 핀은 전압이 떠다니며(floating) HIGH와 LOW를 제멋대로 오갑니다. pinMode(pin, INPUT_PULLUP)을 쓰면 ATmega328P 내부 풀업 저항이 켜져 평소 핀이 5V 쪽으로 당겨져 HIGH로 고정됩니다. 버튼의 반대편을 GND에 연결했다면 버튼을 눌렀을 때 핀이 GND로 떨어져 LOW로 읽힙니다. 그래서 INPUT_PULLUP 버튼 코드는 눌림을 LOW로 판정합니다."},{"h":"analogRead는 10비트 ADC","t":"Uno의 A0~A5는 10비트 ADC에 연결되어 analogRead()가 0~1023의 정수를 돌려줍니다. 기준 전압이 5V일 때 한 단계는 약 5V / 1024 = 약 4.9mV입니다. 전압으로 바꾸려면 value * 5.0 / 1023.0 같은 식을 씁니다. analogRead는 값을 읽는 입력 전용이며 출력과는 무관합니다."},{"h":"analogWrite는 8비트 PWM 듀티","t":"analogWrite(pin, 0~255)는 8비트 듀티비를 지정해 핀을 아주 빠르게 켜고 끕니다. 128이면 대략 50% 시간만 HIGH라 LED가 절반 밝기로 보이고 평균 전압이 약 2.5V처럼 측정됩니다. 하지만 순간 전압은 여전히 0V 아니면 5V이므로 진짜 아날로그 전압을 만드는 DAC와 다릅니다. Uno에서 PWM이 가능한 핀은 3, 5, 6, 9, 10, 11뿐이고 나머지 디지털 핀에 analogWrite를 하면 의도한 밝기 조절이 되지 않습니다."}],"code":{"c":"const int BTN = 2;   // 버튼: 한쪽은 핀2, 반대쪽은 GND\nconst int LED = 9;   // Uno PWM 가능 핀\n\nvoid setup() {\n  pinMode(BTN, INPUT_PULLUP); // 내부 풀업 ON, 평소 HIGH\n  pinMode(LED, OUTPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  int raw = analogRead(A0);          // 0~1023 (10비트)\n  int duty = map(raw, 0, 1023, 0, 255); // 0~255 (8비트 PWM)\n  if (digitalRead(BTN) == LOW) duty = 0; // 눌리면 LOW\n  analogWrite(LED, duty);\n  Serial.println(raw * 5.0 / 1023.0); // 전압 환산\n}","cap":"가변저항 값을 10비트로 읽어 8비트 PWM 듀티로 바꿔 LED 밝기를 조절하고, INPUT_PULLUP 버튼으로 끕니다."},"key":["analogRead는 10비트라 0~1023을 반환하고 5V 기준 한 단계는 약 4.9mV다","analogWrite는 0~255의 8비트 듀티이며 PWM은 평균 전압일 뿐 DAC가 아니다","Uno의 PWM 핀은 3, 5, 6, 9, 10, 11로 제한된다","INPUT_PULLUP은 플로팅을 막고 GND에 연결된 버튼이 눌릴 때 LOW로 읽히게 한다"]}},{"t":"PWM 듀티와 DAC의 차이","q":[{"t":"choice","k":"uno-analogwrite-range","q":"Arduino Uno에서 analogWrite(9, x)의 x가 가질 수 있는 값의 범위는?","ex":"analogWrite는 8비트 듀티를 받으므로 0부터 255까지이며 255가 항상 HIGH(듀티 100%)입니다.\n💡 개념: 0~1023은 analogRead의 10비트 입력 범위라 방향이 반대입니다.\n🛠 실무: analogRead 값을 그대로 analogWrite에 넣으면 값이 잘리므로 map(raw, 0, 1023, 0, 255)로 변환합니다.","o":["0 ~ 1023","0 ~ 100","0 ~ 255","0 ~ 5"],"a":2},{"t":"choice","k":"uno-pwm-pin-list","q":"Arduino Uno에서 analogWrite로 PWM 출력이 가능한 핀들만 모아 놓은 것은?","ex":"Uno에서 PWM은 타이머에 연결된 3, 5, 6, 9, 10, 11번 핀에서만 나오며 보드에도 물결 표시가 되어 있습니다.\n💡 개념: A0~A5는 아날로그 입력 핀이지 PWM 출력 핀이 아닙니다.\n🛠 실무: PWM 아닌 핀에 analogWrite를 하면 값이 128 미만은 LOW, 이상은 HIGH로만 나와 밝기 조절이 안 됩니다.","o":["0, 1, 2, 4, 7, 8","A0 ~ A5 전부","0번부터 13번까지 모든 디지털 핀","3, 5, 6, 9, 10, 11"],"a":3},{"t":"choice","k":"uno-pwm-not-dac","q":"analogWrite(9, 128)을 실행한 Uno의 9번 핀을 오실로스코프로 관찰했습니다. 실제 파형에 대한 설명으로 옳은 것은?","ex":"PWM은 디지털 핀을 빠르게 켜고 꺼서 평균 전압을 조절하는 방식이라 순간 전압은 0V 아니면 5V입니다.\n💡 개념: 듀티 128/255는 약 50%이므로 평균값이 약 2.5V로 측정될 뿐 진짜 2.5V가 아닙니다.\n🛠 실무: 실제 아날로그 전압이 필요하면 RC 저역통과 필터를 붙이거나 MCP4725 같은 외부 DAC를 씁니다.","o":["핀이 계속 정확히 2.5V를 유지하는 평평한 직류가 나온다","0V와 5V를 빠르게 오가며 약 절반의 시간만 HIGH인 사각파가 나온다","0V에서 5V까지 부드럽게 오르내리는 사인파가 나온다","핀이 HIGH로 고정되고 전류만 절반으로 제한된다"],"a":1},{"t":"input","k":"uno-pwm-duty-half-value","q":"Uno에서 LED를 대략 50% 밝기로 만들려면 analogWrite(9, ?)의 물음표에 넣을 값은 얼마입니까? (0~255 범위의 숫자로 답하세요)","ex":"0~255의 절반은 약 127~128이므로 128을 넣으면 듀티가 약 50%가 됩니다.\n💡 개념: 듀티비 = 값 / 255이며 255는 100%, 0은 0%입니다.\n🛠 실무: 사람 눈은 밝기를 로그처럼 느껴 듀티 50%가 절반 밝기로 보이지 않으므로 감마 보정 테이블을 쓰기도 합니다.","a":["128","127","127.5","약 128"]},{"t":"choice","k":"uno-dac-vs-pwm-choice","q":"센서 교정용으로 정확한 1.8V 직류를 만들어 다른 장비에 넣어야 합니다. Uno만 가지고 있을 때 가장 적절한 접근은?","ex":"Uno에는 진짜 DAC가 없으므로 PWM을 RC 필터로 평활하거나 외부 DAC를 붙여야 안정된 직류를 얻습니다.\n💡 개념: analogRead는 입력 전용이고 digitalWrite 반복은 결국 필터 없는 PWM과 같습니다.\n🛠 실무: RC 필터는 응답이 느려지므로 빠른 파형이 필요하면 I2C나 SPI로 붙는 DAC 칩이 낫습니다.","o":["analogWrite로 듀티를 맞추면 그 자체로 정확한 1.8V 직류가 나오므로 그대로 쓴다","analogRead(A0)를 반복 호출하면 A0에 1.8V가 출력된다","PWM 출력에 RC 저역통과 필터를 달거나 외부 DAC 모듈을 사용한다","digitalWrite(9, HIGH)를 아주 짧게 반복 호출해 전압을 낮춘다"],"a":2}],"th":{"sum":"Arduino Uno(ATmega328P)의 핀은 디지털 HIGH/LOW 입출력과 10비트 ADC 입력, 8비트 PWM 출력을 담당합니다. PWM은 평균 전압을 흉내 낼 뿐 진짜 아날로그 출력(DAC)이 아니라는 점이 핵심입니다.","body":[{"h":"pinMode와 디지털 입출력","t":"Arduino Uno에서 핀은 pinMode(pin, OUTPUT)으로 출력, INPUT 또는 INPUT_PULLUP으로 입력이 됩니다. 출력 핀은 digitalWrite(pin, HIGH/LOW)로 5V 또는 0V를 내보냅니다. 입력 핀은 digitalRead(pin)으로 HIGH(1) 또는 LOW(0)만 읽습니다. 즉 디지털 입출력에는 중간값이 없습니다."},{"h":"플로팅 입력과 INPUT_PULLUP","t":"아무 데도 연결되지 않은 입력 핀은 전압이 떠다니며(floating) HIGH와 LOW를 제멋대로 오갑니다. pinMode(pin, INPUT_PULLUP)을 쓰면 ATmega328P 내부 풀업 저항이 켜져 평소 핀이 5V 쪽으로 당겨져 HIGH로 고정됩니다. 버튼의 반대편을 GND에 연결했다면 버튼을 눌렀을 때 핀이 GND로 떨어져 LOW로 읽힙니다. 그래서 INPUT_PULLUP 버튼 코드는 눌림을 LOW로 판정합니다."},{"h":"analogRead는 10비트 ADC","t":"Uno의 A0~A5는 10비트 ADC에 연결되어 analogRead()가 0~1023의 정수를 돌려줍니다. 기준 전압이 5V일 때 한 단계는 약 5V / 1024 = 약 4.9mV입니다. 전압으로 바꾸려면 value * 5.0 / 1023.0 같은 식을 씁니다. analogRead는 값을 읽는 입력 전용이며 출력과는 무관합니다."},{"h":"analogWrite는 8비트 PWM 듀티","t":"analogWrite(pin, 0~255)는 8비트 듀티비를 지정해 핀을 아주 빠르게 켜고 끕니다. 128이면 대략 50% 시간만 HIGH라 LED가 절반 밝기로 보이고 평균 전압이 약 2.5V처럼 측정됩니다. 하지만 순간 전압은 여전히 0V 아니면 5V이므로 진짜 아날로그 전압을 만드는 DAC와 다릅니다. Uno에서 PWM이 가능한 핀은 3, 5, 6, 9, 10, 11뿐이고 나머지 디지털 핀에 analogWrite를 하면 의도한 밝기 조절이 되지 않습니다."}],"code":{"c":"const int BTN = 2;   // 버튼: 한쪽은 핀2, 반대쪽은 GND\nconst int LED = 9;   // Uno PWM 가능 핀\n\nvoid setup() {\n  pinMode(BTN, INPUT_PULLUP); // 내부 풀업 ON, 평소 HIGH\n  pinMode(LED, OUTPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  int raw = analogRead(A0);          // 0~1023 (10비트)\n  int duty = map(raw, 0, 1023, 0, 255); // 0~255 (8비트 PWM)\n  if (digitalRead(BTN) == LOW) duty = 0; // 눌리면 LOW\n  analogWrite(LED, duty);\n  Serial.println(raw * 5.0 / 1023.0); // 전압 환산\n}","cap":"가변저항 값을 10비트로 읽어 8비트 PWM 듀티로 바꿔 LED 밝기를 조절하고, INPUT_PULLUP 버튼으로 끕니다."},"key":["analogRead는 10비트라 0~1023을 반환하고 5V 기준 한 단계는 약 4.9mV다","analogWrite는 0~255의 8비트 듀티이며 PWM은 평균 전압일 뿐 DAC가 아니다","Uno의 PWM 핀은 3, 5, 6, 9, 10, 11로 제한된다","INPUT_PULLUP은 플로팅을 막고 GND에 연결된 버튼이 눌릴 때 LOW로 읽히게 한다"]}},{"t":"직접 이어 보기 — 아날로그 입력과 PWM","th":{"sum":"아날로그 입력(A0~)은 0~5V 를 0~1023 숫자로 읽는다. PWM 출력(~ 표시 핀)은 켜고 끄기를 빠르게 반복해 밝기를 흉내 낸다.","body":[{"h":"가변저항의 세 다리","t":"양끝은 5V 와 GND 에 걸고, 가운데(와이퍼)를 아날로그 핀으로 보낸다. 손잡이를 돌리면 가운데 전압이 0~5V 사이에서 움직인다. 양끝을 거꾸로 걸면 방향만 반대가 되고, **가운데를 안 걸면** 값이 떠다닌다."},{"h":"PWM 은 진짜 아날로그가 아니다","t":"`analogWrite(9, 128)` 은 절반쯤 켜 두는 것이 아니라, 아주 빠르게 켰다 껐다 해서 절반처럼 보이게 하는 것이다. LED 밝기나 모터 속도에는 잘 맞지만, 진짜 전압이 필요한 곳에는 못 쓴다."}],"code":{"c":"int v = analogRead(A0);        // 0~1023\nanalogWrite(9, v / 4);         // 0~255\n// 9번은 ~ 가 붙은 PWM 핀이어야 한다","cap":"읽은 값의 범위와 쓰는 값의 범위가 다르다"},"key":["가변저항 가운데를 아날로그 핀으로","PWM 은 빠르게 껐다 켜는 것","`analogRead` 0~1023, `analogWrite` 0~255"]},"q":[{"k":"가변저항으로 밝기 조절","cat":"internals","q":"가변저항으로 LED 밝기를 조절하는 회로를 만드세요. 가변저항 양끝은 <b>5V·GND</b>, 가운데는 <b>A0</b> 로 보내고, LED 는 <b>PWM 핀 D9</b> 에서 저항을 거쳐 켭니다.","ex":"가변저항은 양끝에 전압을 걸어 두고 가운데에서 나눠진 전압을 꺼내 쓰는 부품입니다. 양끝 중 하나만 걸거나 가운데를 안 걸면 A0 값이 떠다녀요. LED 쪽은 D13 과 똑같이 저항을 직렬로 끼웁니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["A0","D9","5V","GND"]},{"id":"pot","label":"가변저항","pins":["1","W","3"]},{"id":"r","label":"220Ω 저항","pins":["1","2"]},{"id":"led","label":"LED","pins":["+","−"]}],"checks":[{"d":"가변저항 한쪽 끝이 5V 에 붙는다","link":["pot.1","uno.5V"]},{"d":"다른 쪽 끝이 GND 에 붙는다","link":["pot.3","uno.GND"]},{"d":"가운데(W)가 A0 로 간다","link":["pot.W","uno.A0"]},{"d":"D9 가 저항을 거쳐 LED 로 간다","link":["uno.D9","led.+"],"through":"r"},{"d":"LED 의 − 가 GND 로 간다","link":["led.−","uno.GND"]}],"start":[],"sol":[["pot.1","uno.5V"],["pot.3","uno.GND"],["pot.W","uno.A0"],["uno.D9","r.1"],["r.2","led.+"],["led.−","uno.GND"]]},{"k":"잘못된 배선 고치기 — 가운데를 안 걸었다","cat":"internals","q":"가변저항의 <b>가운데 다리가 A0 가 아니라 5V 에</b> 잘못 이어져 있습니다. 잘못된 선을 지우고 바르게 이으세요.","ex":"가운데를 5V 에 붙이면 손잡이를 돌려도 A0 값이 변하지 않습니다. 게다가 가운데와 한쪽 끝이 같은 전위가 되어 그 구간이 합선처럼 동작해요. 가운데는 반드시 읽을 핀으로 보냅니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["A0","5V","GND"]},{"id":"pot","label":"가변저항","pins":["1","W","3"]}],"checks":[{"d":"가운데(W)가 A0 로 간다","link":["pot.W","uno.A0"]},{"d":"가운데가 5V 에 직접 붙어 있지 않다","apart":["pot.W","uno.5V"],"wires":true},{"d":"한쪽 끝이 5V 에 붙는다","link":["pot.1","uno.5V"]},{"d":"다른 쪽 끝이 GND 에 붙는다","link":["pot.3","uno.GND"]}],"start":[["pot.1","uno.5V"],["pot.3","uno.GND"],["pot.W","uno.5V"]],"sol":[["pot.1","uno.5V"],["pot.3","uno.GND"],["pot.W","uno.A0"]]}]}]},{"t":"센서 폴링·외부 인터럽트·millis 논블로킹 타이밍","l":[{"t":"폴링 대신 인터럽트를 쓰는 순간","q":[{"t":"choice","k":"uno-interrupt-pins-list","q":"Arduino Uno에서 attachInterrupt로 외부 인터럽트를 붙일 수 있는 디지털 핀은?","ex":"Uno(ATmega328P)의 외부 인터럽트 INT0/INT1은 디지털 2번과 3번 핀에 연결되어 있습니다.\n💡 개념: 0번과 1번은 UART의 RX/TX로 쓰이고 인터럽트 번호가 아닙니다.\n🛠 실무: 다른 핀에서 변화를 감지하려면 핀 체인지 인터럽트나 관련 라이브러리를 써야 합니다.","o":["0번과 1번","2번과 3번","9번과 10번","13번 하나뿐"],"a":1},{"t":"choice","k":"uno-polling-definition","q":"Arduino Uno에서 loop() 안에서 digitalRead(2)를 계속 호출해 버튼이 눌렸는지 반복 확인하는 방식을 무엇이라 합니까?","ex":"코드가 주기적으로 상태를 직접 확인하는 방식이 폴링이며 인터럽트와 대비됩니다.\n💡 개념: 인터럽트는 반대로 하드웨어가 변화를 감지해 코드를 불러 주는 방식입니다.\n🛠 실무: 폴링은 구현이 단순하지만 loop()가 오래 걸리는 작업에 묶이면 짧은 신호를 놓칠 수 있습니다.","o":["폴링(polling)","인터럽트(interrupt)","디바운싱(debouncing)","슬립 모드(sleep mode)"],"a":0},{"t":"choice","k":"uno-interrupt-use-case","q":"회전 인코더가 아주 짧은 펄스를 빠르게 보내는데 loop()에서 다른 계산도 해야 합니다. 펄스를 놓치지 않으려면?","ex":"짧은 펄스는 폴링 주기 사이에 사라질 수 있으므로 하드웨어가 즉시 잡아 주는 인터럽트가 적합합니다.\n💡 개념: 인터럽트는 실행 중인 코드를 잠시 멈추고 ISR로 뛰어들기 때문에 타이밍이 급한 이벤트에 강합니다.\n🛠 실무: 인코더, 유량계, 타코미터처럼 펄스를 세는 장치는 대부분 인터럽트로 구현합니다.","o":["loop()에 delay(1)을 넣어 루프 속도를 일정하게 맞춘다","펄스 핀을 인터럽트 핀에 연결하고 attachInterrupt로 카운트한다","analogRead로 펄스를 읽어 임계값과 비교한다","Serial 보율을 300으로 낮춰 CPU 부담을 줄인다"],"a":1},{"t":"choice","k":"uno-attachinterrupt-helper","q":"attachInterrupt에 핀 번호를 전달할 때 2 대신 digitalPinToInterrupt(2)를 쓰는 이유로 가장 알맞은 것은?","ex":"보드마다 핀 번호와 인터럽트 번호의 대응이 달라 이를 변환해 주는 매크로가 digitalPinToInterrupt입니다.\n💡 개념: 속도나 디바운싱과는 무관하며 순수하게 번호 매핑용입니다.\n🛠 실무: 이 매크로를 쓰면 Uno에서 Leonardo나 Mega로 옮겨도 코드를 고칠 필요가 줄어듭니다.","o":["인터럽트 처리 속도가 두 배 빨라지기 때문","그 함수가 자동으로 디바운싱까지 처리해 주기 때문","핀 번호를 보드에 맞는 인터럽트 번호로 변환해 이식성을 지켜 주기 때문","ISR 안에서 delay()를 쓸 수 있게 해 주기 때문"],"a":2},{"t":"input","k":"uno-isr-shared-var-keyword","q":"ISR과 loop()가 함께 접근하는 전역 변수 앞에 반드시 붙여야 하는 C++ 키워드는 무엇입니까? (영문 소문자로 입력)","ex":"정답은 volatile로, 컴파일러가 변수 값을 레지스터에 캐시하지 않고 매번 메모리에서 읽게 만듭니다.\n💡 개념: volatile이 없으면 ISR이 값을 바꿔도 loop()가 옛 값을 계속 보는 버그가 생깁니다.\n🛠 실무: 여러 바이트 변수는 volatile만으로 부족해 읽는 동안 noInterrupts()로 잠깐 막아 주기도 합니다.","a":["volatile","VOLATILE","볼라타일"]}],"th":{"sum":"Arduino Uno에서 이벤트를 놓치지 않으려면 폴링과 인터럽트의 차이를 알아야 하고, delay()의 블로킹 특성을 millis() 패턴으로 대체해야 합니다. ISR은 짧게 쓰고 공유 변수는 volatile로 선언합니다.","body":[{"h":"폴링과 인터럽트","t":"폴링은 loop()에서 digitalRead를 반복해 상태가 변했는지 계속 확인하는 방식입니다. 코드가 다른 일로 바쁠 때 짧게 지나가는 신호는 폴링으로 놓칠 수 있습니다. 인터럽트는 하드웨어가 신호 변화를 감지해 현재 실행 중인 코드를 멈추고 즉시 ISR을 호출합니다. Uno에서 attachInterrupt를 쓸 수 있는 외부 인터럽트 핀은 2번과 3번입니다."},{"h":"ISR의 제약","t":"ISR은 최대한 짧아야 하며 보통 플래그를 세우거나 카운터만 올리고 즉시 빠져나옵니다. ISR 안에서는 인터럽트가 꺼져 있어 delay()가 동작하지 않고 millis()도 증가하지 않으며 긴 Serial 출력도 피해야 합니다. ISR과 loop()가 함께 쓰는 변수는 컴파일러 최적화로 값이 캐시되지 않도록 volatile로 선언합니다. 무거운 계산이나 출력은 loop()에서 플래그를 확인한 뒤 처리합니다."},{"h":"delay는 블로킹, millis는 논블로킹","t":"delay(1000)은 1초 동안 CPU를 그 자리에 묶어 두므로 그동안 버튼 확인이나 센서 읽기 같은 다른 일을 전혀 못 합니다. millis()는 보드가 켜진 뒤 흐른 밀리초를 돌려주므로 이전 시각과의 차이를 비교해 시간이 됐을 때만 동작을 실행할 수 있습니다. 이 방식이면 loop()가 계속 돌면서 여러 작업을 번갈아 처리할 수 있습니다. 두 개 이상의 주기가 다른 작업을 동시에 굴릴 때 필수 패턴입니다."},{"h":"디바운싱과 센서 읽기 주기","t":"기계식 버튼은 눌리는 순간 접점이 수 밀리초 동안 떨렸다 붙었다를 반복해 한 번 눌러도 여러 번 눌린 것으로 읽힙니다. 마지막 변화 시각을 저장해 두고 약 20~50ms가 지난 뒤에야 상태를 인정하는 디바운싱으로 해결합니다. 센서도 데이터시트가 정한 최소 변환 시간이 있어 DHT11처럼 초당 1회 정도만 읽어야 하는 경우가 있습니다. 필요 이상으로 자주 읽으면 값이 부정확하거나 이전 값이 그대로 반복됩니다."}],"code":{"c":"volatile unsigned long pulseCount = 0; // ISR과 공유 -> volatile\nunsigned long lastReport = 0;\nconst unsigned long PERIOD = 1000;\n\nvoid onPulse() {   // ISR: 짧게! delay/Serial 금지\n  pulseCount++;\n}\n\nvoid setup() {\n  Serial.begin(9600);\n  pinMode(2, INPUT_PULLUP);            // Uno 외부 인터럽트 핀\n  attachInterrupt(digitalPinToInterrupt(2), onPulse, FALLING);\n}\n\nvoid loop() {\n  unsigned long now = millis();        // 논블로킹 타이밍\n  if (now - lastReport >= PERIOD) {\n    lastReport = now;\n    noInterrupts();\n    unsigned long c = pulseCount;      // 안전하게 복사\n    interrupts();\n    Serial.println(c);                 // 무거운 일은 loop에서\n  }\n}","cap":"ISR은 카운터만 올리고, millis() 비교로 1초마다 논블로킹으로 결과를 출력합니다."},"key":["delay()는 블로킹이라 그동안 아무 일도 못 하므로 millis() 경과 비교 패턴을 쓴다","ISR은 짧게 유지하고 delay()나 긴 Serial 출력을 넣지 않으며 내부에서 millis()는 증가하지 않는다","ISR과 loop()가 공유하는 변수는 반드시 volatile로 선언한다","기계식 버튼은 채터링 때문에 20~50ms 수준의 디바운싱이 필요하다"]}},{"t":"ISR 안에서 하면 안 되는 것","q":[{"t":"choice","k":"uno-isr-millis-frozen","q":"ISR 안에서 millis()를 호출했을 때의 특징으로 옳은 것은?","ex":"millis()는 타이머0 오버플로 인터럽트로 갱신되는데 ISR 실행 중에는 그 인터럽트가 처리되지 않아 값이 멈춥니다.\n💡 개념: 값을 읽는 것 자체는 가능하지만 ISR이 길어져도 값이 늘지 않아 시간 측정에 쓸 수 없습니다.\n🛠 실무: ISR에서 시각을 기록해야 하면 진입 순간의 millis()를 한 번만 저장하고 계산은 loop()에서 합니다.","o":["ISR이 실행되는 동안에는 값이 증가하지 않고 진입 시점의 값으로 고정된다","ISR 안에서는 항상 0을 반환한다","ISR 안에서 호출하면 컴파일 에러가 난다","ISR 안에서는 마이크로초 단위로 정밀도가 올라간다"],"a":0},{"t":"choice","k":"uno-isr-forbidden-delay","q":"ISR 안에 delay(500)을 넣으면 어떤 일이 벌어집니까?","ex":"delay()는 타이머 인터럽트에 의존하는데 ISR 안에서는 인터럽트가 비활성이라 시간이 흐르지 않고 멈춥니다.\n💡 개념: 컴파일은 통과하므로 오류 없이 조용히 오작동하는 위험한 실수입니다.\n🛠 실무: ISR에서는 플래그만 세우고 지연이 필요한 처리는 loop()에서 millis()로 수행합니다.","o":["정상적으로 0.5초를 기다린 뒤 ISR이 끝난다","컴파일 오류가 발생해 업로드 자체가 되지 않는다","ISR 안에서는 인터럽트가 꺼져 있어 delay가 제대로 동작하지 않고 시스템이 멈춘 것처럼 된다","delay가 자동으로 millis 기반 논블로킹으로 바뀐다"],"a":2},{"t":"choice","k":"uno-isr-keep-short","q":"ISR을 최대한 짧게 유지해야 하는 이유로 가장 알맞은 것은?","ex":"ISR 중에는 인터럽트가 막혀 있어 길어질수록 다른 인터럽트, 시리얼 수신, 타이머 갱신이 밀립니다.\n💡 개념: ISR은 카운터 증가나 플래그 설정 정도의 아주 짧은 작업만 담는 것이 원칙입니다.\n🛠 실무: 디버깅용 Serial.println을 ISR에 임시로 넣었다가 수신 데이터가 깨지는 사고가 흔합니다.","o":["ISR이 길면 플래시 메모리를 32KB 넘게 쓰기 때문","ISR이 실행되는 동안 다른 인터럽트와 타이머 처리가 지연되어 이벤트를 놓치기 때문","ISR이 길면 컴파일러가 volatile 선언을 무시하기 때문","ISR이 길면 보율이 자동으로 낮아지기 때문"],"a":1},{"t":"choice","k":"uno-isr-flag-pattern","q":"인터럽트로 감지한 이벤트에 대해 SD 카드 기록처럼 무거운 작업을 해야 합니다. 올바른 구조는?","ex":"ISR은 플래그만 세우고 실제 무거운 작업은 loop()에서 수행하는 것이 표준 패턴입니다.\n💡 개념: 이렇게 나누면 인터럽트 응답성은 유지하면서 긴 작업도 안전하게 처리할 수 있습니다.\n🛠 실무: 플래그를 처리한 뒤에는 곧바로 false로 되돌려 같은 이벤트를 중복 처리하지 않게 합니다.","o":["ISR 안에서 SD 카드 기록까지 모두 끝낸다","ISR에서 volatile 플래그만 true로 세우고 loop()에서 플래그를 보고 기록한다","attachInterrupt를 호출하지 않고 delay로 타이밍을 맞춘다","SD 기록 함수 자체를 ISR로 등록한다"],"a":1},{"t":"choice","k":"uno-isr-serial-print","q":"ISR 안에서 긴 문자열을 Serial.println으로 출력하는 코드가 위험한 이유는?","ex":"9600bps 기준 한 글자에 약 1ms가 걸릴 만큼 시리얼 전송은 느려 ISR이 오래 잡히게 됩니다.\n💡 개념: 시리얼 송신도 인터럽트 기반이라 ISR 안에서는 버퍼가 비워지지 않아 멈출 수 있습니다.\n🛠 실무: 인터럽트 디버깅은 ISR에서 값을 변수에 담고 loop()에서 출력하는 방식으로 합니다.","o":["Serial 출력이 SRAM 2KB를 즉시 모두 소모하기 때문","ISR 안에서는 Serial 객체가 아예 생성되지 않기 때문","시리얼 전송이 상대적으로 느려 ISR이 길어지고 다른 인터럽트 처리가 밀리기 때문","Serial.println이 자동으로 인터럽트를 영구히 끄기 때문"],"a":2}],"th":{"sum":"Arduino Uno에서 이벤트를 놓치지 않으려면 폴링과 인터럽트의 차이를 알아야 하고, delay()의 블로킹 특성을 millis() 패턴으로 대체해야 합니다. ISR은 짧게 쓰고 공유 변수는 volatile로 선언합니다.","body":[{"h":"폴링과 인터럽트","t":"폴링은 loop()에서 digitalRead를 반복해 상태가 변했는지 계속 확인하는 방식입니다. 코드가 다른 일로 바쁠 때 짧게 지나가는 신호는 폴링으로 놓칠 수 있습니다. 인터럽트는 하드웨어가 신호 변화를 감지해 현재 실행 중인 코드를 멈추고 즉시 ISR을 호출합니다. Uno에서 attachInterrupt를 쓸 수 있는 외부 인터럽트 핀은 2번과 3번입니다."},{"h":"ISR의 제약","t":"ISR은 최대한 짧아야 하며 보통 플래그를 세우거나 카운터만 올리고 즉시 빠져나옵니다. ISR 안에서는 인터럽트가 꺼져 있어 delay()가 동작하지 않고 millis()도 증가하지 않으며 긴 Serial 출력도 피해야 합니다. ISR과 loop()가 함께 쓰는 변수는 컴파일러 최적화로 값이 캐시되지 않도록 volatile로 선언합니다. 무거운 계산이나 출력은 loop()에서 플래그를 확인한 뒤 처리합니다."},{"h":"delay는 블로킹, millis는 논블로킹","t":"delay(1000)은 1초 동안 CPU를 그 자리에 묶어 두므로 그동안 버튼 확인이나 센서 읽기 같은 다른 일을 전혀 못 합니다. millis()는 보드가 켜진 뒤 흐른 밀리초를 돌려주므로 이전 시각과의 차이를 비교해 시간이 됐을 때만 동작을 실행할 수 있습니다. 이 방식이면 loop()가 계속 돌면서 여러 작업을 번갈아 처리할 수 있습니다. 두 개 이상의 주기가 다른 작업을 동시에 굴릴 때 필수 패턴입니다."},{"h":"디바운싱과 센서 읽기 주기","t":"기계식 버튼은 눌리는 순간 접점이 수 밀리초 동안 떨렸다 붙었다를 반복해 한 번 눌러도 여러 번 눌린 것으로 읽힙니다. 마지막 변화 시각을 저장해 두고 약 20~50ms가 지난 뒤에야 상태를 인정하는 디바운싱으로 해결합니다. 센서도 데이터시트가 정한 최소 변환 시간이 있어 DHT11처럼 초당 1회 정도만 읽어야 하는 경우가 있습니다. 필요 이상으로 자주 읽으면 값이 부정확하거나 이전 값이 그대로 반복됩니다."}],"code":{"c":"volatile unsigned long pulseCount = 0; // ISR과 공유 -> volatile\nunsigned long lastReport = 0;\nconst unsigned long PERIOD = 1000;\n\nvoid onPulse() {   // ISR: 짧게! delay/Serial 금지\n  pulseCount++;\n}\n\nvoid setup() {\n  Serial.begin(9600);\n  pinMode(2, INPUT_PULLUP);            // Uno 외부 인터럽트 핀\n  attachInterrupt(digitalPinToInterrupt(2), onPulse, FALLING);\n}\n\nvoid loop() {\n  unsigned long now = millis();        // 논블로킹 타이밍\n  if (now - lastReport >= PERIOD) {\n    lastReport = now;\n    noInterrupts();\n    unsigned long c = pulseCount;      // 안전하게 복사\n    interrupts();\n    Serial.println(c);                 // 무거운 일은 loop에서\n  }\n}","cap":"ISR은 카운터만 올리고, millis() 비교로 1초마다 논블로킹으로 결과를 출력합니다."},"key":["delay()는 블로킹이라 그동안 아무 일도 못 하므로 millis() 경과 비교 패턴을 쓴다","ISR은 짧게 유지하고 delay()나 긴 Serial 출력을 넣지 않으며 내부에서 millis()는 증가하지 않는다","ISR과 loop()가 공유하는 변수는 반드시 volatile로 선언한다","기계식 버튼은 채터링 때문에 20~50ms 수준의 디바운싱이 필요하다"]}},{"t":"millis 논블로킹과 버튼 디바운싱","q":[{"t":"choice","k":"uno-button-bounce-symptom","q":"버튼을 한 번만 눌렀는데 카운터가 3~4씩 올라갑니다. 가장 유력한 원인은?","ex":"기계식 스위치는 접촉 순간 수 밀리초 동안 붙었다 떨어지기를 반복해 여러 번의 입력 변화로 읽힙니다.\n💡 개념: 이 현상을 채터링 또는 바운스라 하고, 이를 걸러내는 처리가 디바운싱입니다.\n🛠 실무: 소프트웨어 디바운싱이 가장 쉽고, 노이즈가 심하면 RC 회로나 슈미트 트리거를 추가합니다.","o":["analogRead의 10비트 분해능이 부족해서","PWM 핀이 아닌 곳에 버튼을 연결해서","기계식 접점이 순간적으로 떨리는 채터링(바운스) 때문","보율이 9600이 아니라 115200이라서"],"a":2},{"t":"choice","k":"uno-delay-blocking-reason","q":"loop()에서 delay(1000)을 쓰면 생기는 문제로 가장 정확한 것은?","ex":"delay()는 블로킹 함수라 지정한 시간 동안 코드 진행이 멈춰 다른 일을 전혀 처리하지 못합니다.\n💡 개념: 전원이나 millis 값에는 영향이 없고 단지 실행 흐름만 붙잡습니다.\n🛠 실무: LED 깜빡임과 버튼 반응을 동시에 원하면 delay 대신 millis 비교로 바꿔야 합니다.","o":["1초 동안 CPU가 그 자리에 묶여 버튼 확인 같은 다른 작업을 하지 못한다","1초 동안 보드 전원이 꺼져 재부팅된다","delay 이후 millis() 값이 0으로 초기화된다","delay는 SRAM을 1KB씩 소모해 메모리가 부족해진다"],"a":0},{"t":"input","k":"uno-debounce-typical-ms","q":"기계식 버튼의 소프트웨어 디바운싱에 흔히 쓰는 지연 시간은 대략 몇 밀리초 수준입니까? (예: 50ms, 20~50, 50)","ex":"보통 20~50ms 정도면 접점 떨림이 가라앉아 안정된 상태를 읽을 수 있습니다.\n💡 개념: 너무 짧으면 바운스가 남고 너무 길면 빠른 연속 입력을 놓칩니다.\n🛠 실무: 마지막 상태 변화 시각을 millis()로 저장하고 그 시간이 지난 뒤에만 상태를 확정하는 방식이 표준입니다.","a":["50","50ms","20~50","20~50ms"]},{"t":"choice","k":"uno-millis-nonblocking-pattern","q":"delay 없이 500ms마다 LED를 토글하는 논블로킹 코드로 올바른 것은?","ex":"이전 실행 시각과 현재 millis()의 차이를 목표 간격과 비교하고, 실행 후 기준 시각을 갱신하는 것이 표준 패턴입니다.\n💡 개념: millis()는 계속 증가하므로 특정 값과 == 로 비교하면 그 순간을 놓치기 쉽습니다.\n🛠 실무: 뺄셈 비교 방식은 약 49일 후 millis()가 넘칠 때도 unsigned 연산 덕분에 안전하게 동작합니다.","o":["if (millis() == 500) { toggle(); }","if (millis() - lastToggle &gt;= 500) { lastToggle = millis(); toggle(); }","if (millis() &gt; 500) { delay(500); toggle(); }","while (millis() &lt; 500) { toggle(); }"],"a":1},{"t":"choice","k":"uno-sensor-read-interval","q":"DHT11처럼 데이터시트에 최소 읽기 간격이 있는 센서를 loop()에서 지연 없이 매 루프마다 읽으면 생기는 일은?","ex":"센서마다 내부 측정과 변환에 필요한 최소 시간이 있어 그보다 자주 요청하면 실패하거나 캐시된 값이 나옵니다.\n💡 개념: DHT11은 대략 1초에 한 번 정도가 권장 주기입니다.\n🛠 실무: 센서 읽기도 delay 대신 millis() 비교로 주기를 지키면 다른 작업을 막지 않습니다.","o":["센서가 매번 더 정확한 값을 돌려준다","변환 시간이 부족해 읽기가 실패하거나 이전 값이 그대로 반복된다","보드의 플래시 메모리가 손상된다","analogWrite의 듀티가 자동으로 0이 된다"],"a":1}],"th":{"sum":"Arduino Uno에서 이벤트를 놓치지 않으려면 폴링과 인터럽트의 차이를 알아야 하고, delay()의 블로킹 특성을 millis() 패턴으로 대체해야 합니다. ISR은 짧게 쓰고 공유 변수는 volatile로 선언합니다.","body":[{"h":"폴링과 인터럽트","t":"폴링은 loop()에서 digitalRead를 반복해 상태가 변했는지 계속 확인하는 방식입니다. 코드가 다른 일로 바쁠 때 짧게 지나가는 신호는 폴링으로 놓칠 수 있습니다. 인터럽트는 하드웨어가 신호 변화를 감지해 현재 실행 중인 코드를 멈추고 즉시 ISR을 호출합니다. Uno에서 attachInterrupt를 쓸 수 있는 외부 인터럽트 핀은 2번과 3번입니다."},{"h":"ISR의 제약","t":"ISR은 최대한 짧아야 하며 보통 플래그를 세우거나 카운터만 올리고 즉시 빠져나옵니다. ISR 안에서는 인터럽트가 꺼져 있어 delay()가 동작하지 않고 millis()도 증가하지 않으며 긴 Serial 출력도 피해야 합니다. ISR과 loop()가 함께 쓰는 변수는 컴파일러 최적화로 값이 캐시되지 않도록 volatile로 선언합니다. 무거운 계산이나 출력은 loop()에서 플래그를 확인한 뒤 처리합니다."},{"h":"delay는 블로킹, millis는 논블로킹","t":"delay(1000)은 1초 동안 CPU를 그 자리에 묶어 두므로 그동안 버튼 확인이나 센서 읽기 같은 다른 일을 전혀 못 합니다. millis()는 보드가 켜진 뒤 흐른 밀리초를 돌려주므로 이전 시각과의 차이를 비교해 시간이 됐을 때만 동작을 실행할 수 있습니다. 이 방식이면 loop()가 계속 돌면서 여러 작업을 번갈아 처리할 수 있습니다. 두 개 이상의 주기가 다른 작업을 동시에 굴릴 때 필수 패턴입니다."},{"h":"디바운싱과 센서 읽기 주기","t":"기계식 버튼은 눌리는 순간 접점이 수 밀리초 동안 떨렸다 붙었다를 반복해 한 번 눌러도 여러 번 눌린 것으로 읽힙니다. 마지막 변화 시각을 저장해 두고 약 20~50ms가 지난 뒤에야 상태를 인정하는 디바운싱으로 해결합니다. 센서도 데이터시트가 정한 최소 변환 시간이 있어 DHT11처럼 초당 1회 정도만 읽어야 하는 경우가 있습니다. 필요 이상으로 자주 읽으면 값이 부정확하거나 이전 값이 그대로 반복됩니다."}],"code":{"c":"volatile unsigned long pulseCount = 0; // ISR과 공유 -> volatile\nunsigned long lastReport = 0;\nconst unsigned long PERIOD = 1000;\n\nvoid onPulse() {   // ISR: 짧게! delay/Serial 금지\n  pulseCount++;\n}\n\nvoid setup() {\n  Serial.begin(9600);\n  pinMode(2, INPUT_PULLUP);            // Uno 외부 인터럽트 핀\n  attachInterrupt(digitalPinToInterrupt(2), onPulse, FALLING);\n}\n\nvoid loop() {\n  unsigned long now = millis();        // 논블로킹 타이밍\n  if (now - lastReport >= PERIOD) {\n    lastReport = now;\n    noInterrupts();\n    unsigned long c = pulseCount;      // 안전하게 복사\n    interrupts();\n    Serial.println(c);                 // 무거운 일은 loop에서\n  }\n}","cap":"ISR은 카운터만 올리고, millis() 비교로 1초마다 논블로킹으로 결과를 출력합니다."},"key":["delay()는 블로킹이라 그동안 아무 일도 못 하므로 millis() 경과 비교 패턴을 쓴다","ISR은 짧게 유지하고 delay()나 긴 Serial 출력을 넣지 않으며 내부에서 millis()는 증가하지 않는다","ISR과 loop()가 공유하는 변수는 반드시 volatile로 선언한다","기계식 버튼은 채터링 때문에 20~50ms 수준의 디바운싱이 필요하다"]}},{"t":"직접 이어 보기 — 센서와 인터럽트 핀","th":{"sum":"센서 대부분은 전원(VCC)·접지(GND)·신호(OUT) 세 가닥이다. 세 가닥이 다 있어야 값을 준다.","body":[{"h":"전원을 빼먹으면","t":"신호선만 잇고 VCC 를 안 걸면 센서가 아예 동작하지 않는다. 값이 0으로 고정되거나 떠다니는데, 코드를 아무리 봐도 원인이 안 보인다. 센서가 이상하면 **전원·접지·신호 세 가닥부터** 확인한다."},{"h":"인터럽트 핀","t":"Uno 에서 외부 인터럽트를 쓸 수 있는 핀은 **D2 와 D3 뿐**이다. 다른 핀에 물리고 `attachInterrupt` 를 부르면 동작하지 않는다. 빠르게 지나가는 신호(회전 센서·엔코더)는 폴링으로 놓치기 쉬워 인터럽트 핀에 물린다."}],"code":{"c":"attachInterrupt(digitalPinToInterrupt(2), onEdge, RISING);\n// Uno 는 D2·D3 만 된다","cap":"센서는 세 가닥, 인터럽트는 D2·D3"},"key":["센서는 VCC·GND·OUT 세 가닥","전원을 빼먹으면 값이 안 나온다","Uno 인터럽트는 D2·D3"]},"q":[{"k":"모션 센서 세 가닥 잇기","cat":"internals","q":"모션 센서를 이으세요. <b>VCC 는 5V</b>, <b>GND 는 GND</b>, <b>OUT 은 인터럽트가 되는 핀</b>에 물려야 합니다.","ex":"Uno 에서 attachInterrupt 를 쓸 수 있는 핀은 D2 와 D3 뿐입니다. D7 에 물리면 코드가 맞아도 인터럽트가 걸리지 않아요. 그리고 VCC 를 빼먹으면 센서 자체가 안 돌아 OUT 값이 의미가 없습니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["D2","D7","5V","GND"]},{"id":"pir","label":"모션 센서","pins":["VCC","OUT","GND"]}],"checks":[{"d":"VCC 가 5V 에 붙는다","link":["pir.VCC","uno.5V"]},{"d":"GND 가 GND 에 붙는다","link":["pir.GND","uno.GND"]},{"d":"OUT 이 인터럽트 핀(D2)으로 간다","link":["pir.OUT","uno.D2"]},{"d":"OUT 이 D7 에 붙어 있지 않다","apart":["pir.OUT","uno.D7"],"wires":true},{"d":"5V 와 GND 가 바로 붙어 있지 않다","apart":["uno.5V","uno.GND"],"wires":true}],"start":[],"sol":[["pir.VCC","uno.5V"],["pir.GND","uno.GND"],["pir.OUT","uno.D2"]]},{"k":"전원을 빼먹은 배선 고치기","cat":"internals","q":"온도 센서의 <b>신호선만</b> 이어져 있습니다. 값이 안 나오는 이유를 찾아 <b>빠진 두 가닥</b>을 마저 이으세요.","ex":"신호선만 이으면 센서에 전원이 없어 아무 값도 만들지 못합니다. A1 은 떠다니는 값을 읽어요 — 숫자가 나오니까 동작하는 것처럼 보여서 더 헷갈립니다. 센서가 이상하면 세 가닥부터 확인하세요.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["A1","5V","GND"]},{"id":"tmp","label":"온도 센서","pins":["VCC","OUT","GND"]}],"checks":[{"d":"OUT 이 A1 로 간다","link":["tmp.OUT","uno.A1"]},{"d":"VCC 가 5V 에 붙는다","link":["tmp.VCC","uno.5V"]},{"d":"GND 가 GND 에 붙는다","link":["tmp.GND","uno.GND"]},{"d":"VCC 와 GND 가 서로 붙어 있지 않다","apart":["tmp.VCC","tmp.GND"],"wires":true}],"start":[["tmp.OUT","uno.A1"]],"sol":[["tmp.OUT","uno.A1"],["tmp.VCC","uno.5V"],["tmp.GND","uno.GND"]]}]}]},{"t":"UART·I2C·SPI 통신과 전력·메모리 제약","l":[{"t":"UART 보율과 시리얼 디버깅","q":[{"t":"choice","k":"uart-uno-rx-tx-pins","q":"Arduino Uno의 하드웨어 시리얼(UART)이 연결된 디지털 핀 번호는?","ex":"Uno의 하드웨어 UART는 디지털 0번 RX, 1번 TX에 연결되어 있고 USB 통신과 공유됩니다.\n💡 개념: A4/A5는 I2C, 11/12/13은 SPI, 2/3은 외부 인터럽트 핀입니다.\n🛠 실무: 0번과 1번에 모듈을 꽂아 둔 채 업로드하면 실패하므로 업로드 전에 잠시 분리합니다.","o":["A4와 A5","0번(RX)과 1번(TX)","11번과 12번","2번과 3번"],"a":1},{"t":"input","k":"uart-common-baud-value","q":"아두이노 예제에서 Serial.begin()에 가장 흔히 쓰이는 기본 보율 값은 무엇입니까? (숫자만 입력, 예: 9600)","ex":"아두이노 기본 예제와 시리얼 모니터의 기본값이 모두 9600bps입니다.\n💡 개념: 보율은 초당 전송되는 심볼 수로 9600bps면 한 글자에 대략 1ms 정도가 걸립니다.\n🛠 실무: 로그가 많아 loop가 느려지면 115200으로 올려 전송 시간을 줄이고 모니터 설정도 함께 바꿉니다.","a":["9600","9600bps","9600 bps"]},{"t":"choice","k":"uart-no-clock-line","q":"UART가 I2C나 SPI와 결정적으로 다른 점은?","ex":"UART는 별도의 클럭선 없이 시작 비트와 약속된 보율로 타이밍을 맞추는 비동기 방식입니다.\n💡 개념: I2C의 SCL, SPI의 SCK가 클럭선이며 이들은 동기 통신입니다.\n🛠 실무: 클럭이 없어 배선은 단순하지만 양쪽 클럭 오차가 크면 장거리에서 오류율이 올라갑니다.","o":["클럭 신호선이 없는 비동기 통신이라 양쪽이 같은 보율을 미리 약속해야 한다","한 선으로 데이터와 클럭을 함께 보낸다","항상 마스터가 슬레이브 주소를 먼저 전송한다","전이중 통신이 불가능하다"],"a":0},{"t":"choice","k":"uart-baud-mismatch-symptom","q":"Uno 코드에 Serial.begin(9600)을 썼는데 시리얼 모니터를 115200으로 열었습니다. 화면에 나타나는 현상은?","ex":"UART는 클럭선 없이 양쪽이 약속한 보율로 비트를 샘플링하므로 속도가 다르면 비트 경계를 잘못 읽어 깨진 문자가 나옵니다.\n💡 개념: 아두이노 UART에는 보율 자동 협상 기능이 없습니다.\n🛠 실무: 출력이 깨지면 코드의 Serial.begin 값과 모니터 우하단 보율 설정부터 맞춰 보세요.","o":["아무것도 출력되지 않고 보드가 리셋된다","정상적으로 출력되지만 속도만 느려진다","의미를 알 수 없는 깨진 문자가 출력된다","자동으로 보율이 맞춰져 정상 출력된다"],"a":2},{"t":"choice","k":"uart-two-device-wiring","q":"Uno와 GPS 모듈을 UART로 연결할 때 올바른 배선은?","ex":"한쪽이 보내는 TX는 상대가 받는 RX로 들어가야 하므로 두 선을 교차해서 연결합니다.\n💡 개념: SDA/SCL은 I2C, MOSI/MISO/SCK는 SPI의 배선이라 UART와 다릅니다.\n🛠 실무: GND를 공통으로 묶지 않으면 기준 전압이 달라 통신이 되지 않으니 GND도 반드시 연결합니다.","o":["Uno의 TX를 모듈의 TX에, RX를 모듈의 RX에 연결한다","SDA와 SCL 두 선을 연결하고 풀업 저항을 단다","Uno의 TX를 모듈의 RX에, Uno의 RX를 모듈의 TX에 교차 연결한다","MOSI, MISO, SCK 세 선을 연결하고 CS를 추가한다"],"a":2}],"th":{"sum":"Arduino Uno는 UART, I2C, SPI 세 가지 통신을 지원하며 각각 선 개수, 속도, 장치 선택 방식이 다릅니다. 동시에 SRAM 2KB와 플래시 32KB라는 좁은 자원 안에서 전력까지 아껴야 합니다.","body":[{"h":"UART와 보율","t":"UART는 TX와 RX 두 선으로 데이터를 주고받는 비동기 통신이라 클럭선이 따로 없습니다. 대신 양쪽이 미리 같은 보율(baud rate)로 약속해야 하고, Serial.begin(9600)과 시리얼 모니터 설정이 다르면 화면에 깨진 문자가 쏟아집니다. Uno에서 하드웨어 시리얼은 디지털 0번(RX)과 1번(TX) 핀에 연결되어 있고 USB 업로드와 공유됩니다. 그래서 0번과 1번 핀에 장치를 연결한 채로 업로드하면 실패하기 쉽습니다."},{"h":"I2C는 2선 공유와 주소","t":"I2C는 SDA(데이터)와 SCL(클럭) 단 두 선을 여러 장치가 함께 씁니다. 마스터가 7비트 주소를 먼저 보내 그 주소를 가진 슬레이브 하나만 응답하게 만들어 장치를 구분합니다. 두 선 모두 풀업 저항이 필요하고 대개 4.7k옴 정도를 씁니다. 같은 주소를 가진 장치를 두 개 붙이면 충돌해서 둘 다 제대로 동작하지 않으므로 주소 점퍼를 바꾸거나 I2C 멀티플렉서를 씁니다. Uno의 I2C 핀은 A4(SDA)와 A5(SCL)입니다."},{"h":"SPI는 빠르지만 핀을 더 쓴다","t":"SPI는 MOSI, MISO, SCK 세 선을 모든 슬레이브가 공유하고, 슬레이브마다 별도의 CS(SS) 선을 하나씩 더 연결해 통신할 상대를 고릅니다. 주소 개념 없이 CS를 LOW로 내려 선택하므로 슬레이브가 늘면 핀도 그만큼 늘어납니다. 대신 클럭 속도가 높고 전이중이라 I2C보다 훨씬 빠릅니다. Uno에서는 11(MOSI), 12(MISO), 13(SCK), 10(기본 SS)이 SPI 핀입니다."},{"h":"전력과 메모리 제약","t":"배터리로 오래 동작해야 하면 avr/sleep.h의 슬립 모드로 CPU를 재우고 인터럽트나 워치독으로 깨우는 방식이 효과적입니다. Uno의 ATmega328P는 SRAM이 2KB뿐이라 문자열이나 배열을 많이 쓰면 금세 부족해지고 재부팅이나 이상 동작이 납니다. Serial.println(F(\"메시지\")) 처럼 F() 매크로로 문자열 리터럴을 32KB 플래시에 남겨 두면 RAM을 아낄 수 있습니다. 컴파일 후 출력되는 전역 변수 사용량 경고를 항상 확인하는 습관이 필요합니다."}],"code":{"c":"#include <Wire.h>\n#include <SPI.h>\n\nconst int CS_PIN = 10; // SPI 슬레이브별 CS\n\nvoid setup() {\n  Serial.begin(9600);          // 시리얼 모니터도 9600으로 맞출 것\n  Serial.println(F(\"boot ok\")); // F(): 문자열을 플래시에 두어 SRAM 절약\n\n  Wire.begin();                // I2C: A4=SDA, A5=SCL (풀업 필요)\n  Wire.beginTransmission(0x3C); // 7비트 주소로 슬레이브 지정\n  Wire.write(0x00);\n  Wire.endTransmission();\n\n  pinMode(CS_PIN, OUTPUT);\n  digitalWrite(CS_PIN, HIGH);  // 평소 비선택\n  SPI.begin();\n}\n\nvoid loop() {\n  digitalWrite(CS_PIN, LOW);   // 이 슬레이브만 선택\n  byte v = SPI.transfer(0x00);\n  digitalWrite(CS_PIN, HIGH);\n  Serial.println(v);\n  delay(1000);\n}","cap":"I2C는 7비트 주소로, SPI는 CS 핀으로 상대를 고르며 F() 매크로로 SRAM을 아낍니다."},"key":["UART는 클럭선 없이 비동기라 양쪽 보율이 다르면 깨진 문자가 나온다","I2C는 SDA/SCL 2선을 공유하고 7비트 주소로 슬레이브를 구분하며 풀업 저항이 필요하다","SPI는 MOSI/MISO/SCK 공유에 슬레이브마다 CS가 필요해 빠르지만 핀을 더 쓴다","Uno는 SRAM 2KB·플래시 32KB이며 F() 매크로로 문자열을 플래시에 두면 RAM을 절약한다"]}},{"t":"I2C 주소 충돌과 SPI 슬레이브 선택","q":[{"t":"choice","k":"i2c-two-wire-names","q":"I2C 통신이 사용하는 두 신호선의 이름은?","ex":"I2C는 데이터선 SDA와 클럭선 SCL 두 가닥을 모든 장치가 공유합니다.\n💡 개념: MOSI/MISO는 SPI, TX/RX는 UART의 신호선이고 VCC/GND는 전원입니다.\n🛠 실무: Uno에서는 A4가 SDA, A5가 SCL이며 보드 상단에 별도 SDA/SCL 핀도 병렬로 나와 있습니다.","o":["SDA와 SCL","MOSI와 MISO","TX와 RX","VCC와 GND"],"a":0},{"t":"choice","k":"i2c-address-collision","q":"같은 7비트 주소 0x68을 가진 I2C 센서 두 개를 하나의 SDA/SCL 버스에 함께 연결하면?","ex":"I2C는 주소로만 상대를 구분하므로 같은 주소 장치가 둘이면 동시에 응답해 데이터가 깨집니다.\n💡 개념: 아두이노에는 주소를 자동 재할당하는 기능이 없습니다.\n🛠 실무: 주소 설정 핀(AD0)이나 점퍼로 주소를 바꾸거나 TCA9548A 같은 I2C 멀티플렉서를 사용합니다.","o":["아두이노가 자동으로 두 번째 장치에 새 주소를 부여한다","두 장치가 같은 주소에 동시에 응답해 충돌하고 값이 제대로 읽히지 않는다","첫 번째 장치만 인식되고 두 번째는 안전하게 무시되어 문제가 없다","SPI 모드로 자동 전환되어 정상 동작한다"],"a":1},{"t":"choice","k":"spi-slave-select-mechanism","q":"SPI 버스에 슬레이브를 3개 연결할 때 통신할 대상을 고르는 방법은?","ex":"SPI에는 주소 개념이 없고 MOSI/MISO/SCK는 공유하되 CS 라인으로 대상을 하나씩 선택합니다.\n💡 개념: 선택되지 않은 슬레이브는 CS가 HIGH라 MISO를 고임피던스로 두어 버스를 방해하지 않습니다.\n🛠 실무: 슬레이브가 늘수록 CS 핀이 하나씩 더 필요해 Uno에서는 핀 부족이 금방 옵니다.","o":["각 슬레이브에 7비트 주소를 먼저 전송한다","슬레이브마다 별도의 CS(SS) 핀을 두고 통신할 슬레이브의 CS만 LOW로 내린다","보율을 슬레이브마다 다르게 설정해 구분한다","MISO 선을 슬레이브마다 따로 배선한다"],"a":1},{"t":"choice","k":"spi-vs-i2c-tradeoff","q":"SD 카드처럼 큰 데이터를 빠르게 주고받아야 할 때 I2C보다 SPI가 유리한 이유와 그 대가는?","ex":"SPI는 높은 클럭과 전이중 덕분에 빠르지만 공유선 3개에 더해 슬레이브 수만큼 CS 핀이 필요합니다.\n💡 개념: I2C는 2선으로 끝나 핀이 절약되지만 속도가 낮고 주소 충돌 문제가 있습니다.\n🛠 실무: 디스플레이나 SD 카드처럼 데이터량이 큰 장치는 SPI, 저속 센서는 I2C로 나눠 붙이는 구성이 흔합니다.","o":["SPI가 더 빠르지만 슬레이브마다 CS가 필요해 핀을 더 많이 쓴다","SPI가 더 느리지만 선이 2개뿐이라 배선이 간단하다","SPI가 더 빠르고 선도 I2C보다 적어 모든 면에서 유리하다","SPI는 클럭선이 없어 배선이 줄지만 보율을 맞춰야 한다"],"a":0},{"t":"choice","k":"i2c-pullup-requirement","q":"I2C 버스에서 SDA와 SCL에 풀업 저항이 필요한 이유는?","ex":"I2C 장치는 라인을 LOW로 당기기만 할 수 있어서 풀업 저항이 라인을 HIGH로 복귀시켜야 합니다.\n💡 개념: 흔히 4.7k옴 정도를 쓰고, 대부분의 브레이크아웃 보드에는 이미 내장되어 있습니다.\n🛠 실무: 모듈을 여러 개 연결하면 내장 풀업이 병렬로 걸려 저항이 너무 낮아질 수 있으니 일부를 제거하기도 합니다.","o":["슬레이브 주소를 7비트로 제한하기 위해","클럭 속도를 SPI 수준으로 끌어올리기 위해","장치들이 라인을 LOW로만 끌 수 있는 오픈 드레인 구조라 HIGH로 되돌릴 수단이 필요해서","5V 장치와 3.3V 장치의 전압을 자동 변환하기 위해"],"a":2}],"th":{"sum":"Arduino Uno는 UART, I2C, SPI 세 가지 통신을 지원하며 각각 선 개수, 속도, 장치 선택 방식이 다릅니다. 동시에 SRAM 2KB와 플래시 32KB라는 좁은 자원 안에서 전력까지 아껴야 합니다.","body":[{"h":"UART와 보율","t":"UART는 TX와 RX 두 선으로 데이터를 주고받는 비동기 통신이라 클럭선이 따로 없습니다. 대신 양쪽이 미리 같은 보율(baud rate)로 약속해야 하고, Serial.begin(9600)과 시리얼 모니터 설정이 다르면 화면에 깨진 문자가 쏟아집니다. Uno에서 하드웨어 시리얼은 디지털 0번(RX)과 1번(TX) 핀에 연결되어 있고 USB 업로드와 공유됩니다. 그래서 0번과 1번 핀에 장치를 연결한 채로 업로드하면 실패하기 쉽습니다."},{"h":"I2C는 2선 공유와 주소","t":"I2C는 SDA(데이터)와 SCL(클럭) 단 두 선을 여러 장치가 함께 씁니다. 마스터가 7비트 주소를 먼저 보내 그 주소를 가진 슬레이브 하나만 응답하게 만들어 장치를 구분합니다. 두 선 모두 풀업 저항이 필요하고 대개 4.7k옴 정도를 씁니다. 같은 주소를 가진 장치를 두 개 붙이면 충돌해서 둘 다 제대로 동작하지 않으므로 주소 점퍼를 바꾸거나 I2C 멀티플렉서를 씁니다. Uno의 I2C 핀은 A4(SDA)와 A5(SCL)입니다."},{"h":"SPI는 빠르지만 핀을 더 쓴다","t":"SPI는 MOSI, MISO, SCK 세 선을 모든 슬레이브가 공유하고, 슬레이브마다 별도의 CS(SS) 선을 하나씩 더 연결해 통신할 상대를 고릅니다. 주소 개념 없이 CS를 LOW로 내려 선택하므로 슬레이브가 늘면 핀도 그만큼 늘어납니다. 대신 클럭 속도가 높고 전이중이라 I2C보다 훨씬 빠릅니다. Uno에서는 11(MOSI), 12(MISO), 13(SCK), 10(기본 SS)이 SPI 핀입니다."},{"h":"전력과 메모리 제약","t":"배터리로 오래 동작해야 하면 avr/sleep.h의 슬립 모드로 CPU를 재우고 인터럽트나 워치독으로 깨우는 방식이 효과적입니다. Uno의 ATmega328P는 SRAM이 2KB뿐이라 문자열이나 배열을 많이 쓰면 금세 부족해지고 재부팅이나 이상 동작이 납니다. Serial.println(F(\"메시지\")) 처럼 F() 매크로로 문자열 리터럴을 32KB 플래시에 남겨 두면 RAM을 아낄 수 있습니다. 컴파일 후 출력되는 전역 변수 사용량 경고를 항상 확인하는 습관이 필요합니다."}],"code":{"c":"#include <Wire.h>\n#include <SPI.h>\n\nconst int CS_PIN = 10; // SPI 슬레이브별 CS\n\nvoid setup() {\n  Serial.begin(9600);          // 시리얼 모니터도 9600으로 맞출 것\n  Serial.println(F(\"boot ok\")); // F(): 문자열을 플래시에 두어 SRAM 절약\n\n  Wire.begin();                // I2C: A4=SDA, A5=SCL (풀업 필요)\n  Wire.beginTransmission(0x3C); // 7비트 주소로 슬레이브 지정\n  Wire.write(0x00);\n  Wire.endTransmission();\n\n  pinMode(CS_PIN, OUTPUT);\n  digitalWrite(CS_PIN, HIGH);  // 평소 비선택\n  SPI.begin();\n}\n\nvoid loop() {\n  digitalWrite(CS_PIN, LOW);   // 이 슬레이브만 선택\n  byte v = SPI.transfer(0x00);\n  digitalWrite(CS_PIN, HIGH);\n  Serial.println(v);\n  delay(1000);\n}","cap":"I2C는 7비트 주소로, SPI는 CS 핀으로 상대를 고르며 F() 매크로로 SRAM을 아낍니다."},"key":["UART는 클럭선 없이 비동기라 양쪽 보율이 다르면 깨진 문자가 나온다","I2C는 SDA/SCL 2선을 공유하고 7비트 주소로 슬레이브를 구분하며 풀업 저항이 필요하다","SPI는 MOSI/MISO/SCK 공유에 슬레이브마다 CS가 필요해 빠르지만 핀을 더 쓴다","Uno는 SRAM 2KB·플래시 32KB이며 F() 매크로로 문자열을 플래시에 두면 RAM을 절약한다"]}},{"t":"SRAM 2KB 제약과 저전력 설계","q":[{"t":"choice","k":"uno-memory-sizes","q":"Arduino Uno(ATmega328P)의 SRAM과 플래시 용량으로 옳은 것은?","ex":"ATmega328P는 SRAM 2KB, 플래시 32KB, EEPROM 1KB를 갖습니다.\n💡 개념: 플래시는 프로그램 코드가, SRAM은 실행 중 변수가 들어가는 공간입니다.\n🛠 실무: 컴파일 결과에 나오는 전역 변수 사용량이 SRAM의 70%를 넘기 시작하면 불안정해질 수 있습니다.","o":["SRAM 32KB, 플래시 2KB","SRAM 2KB, 플래시 32KB","SRAM 512KB, 플래시 4MB","SRAM 1KB, 플래시 1KB"],"a":1},{"t":"choice","k":"uno-sleep-power-saving","q":"배터리로 몇 달간 동작해야 하는 Uno 기반 센서 노드의 전력 소모를 줄이는 가장 효과적인 방법은?","ex":"delay()는 CPU가 계속 전력을 쓰며 도는 것이라 절전 효과가 없고, 슬립 모드는 CPU와 주변장치를 실제로 꺼 소비 전류를 크게 낮춥니다.\n💡 개념: 깨우는 방법은 외부 인터럽트나 워치독 타이머가 대표적입니다.\n🛠 실무: 보드의 전원 LED와 레귤레이터도 상당한 전류를 먹으므로 저전력 설계에서는 베어 ATmega328P 회로를 따로 만들기도 합니다.","o":["loop()에 delay(60000)을 넣어 1분씩 쉬게 한다","Serial.begin의 보율을 300으로 낮춘다","슬립 모드로 CPU를 재우고 인터럽트나 워치독 타이머로 깨운다","analogWrite 듀티를 0으로 고정한다"],"a":2},{"t":"input","k":"uno-flash-string-macro-name","q":"문자열 리터럴을 플래시 메모리에 두어 SRAM을 아끼게 해 주는 아두이노 매크로의 이름을 적으세요. (예: 괄호 포함 또는 문자 하나)","ex":"정답은 F() 매크로이며 Serial.println(F(\"text\")) 형태로 사용합니다.\n💡 개념: 내부적으로 PROGMEM에 문자열을 두고 필요할 때만 읽어 오는 방식입니다.\n🛠 실무: 변수 배열을 플래시에 두려면 PROGMEM과 pgm_read 계열 함수를 함께 씁니다.","a":["F()","F","f()","F 매크로"]},{"t":"choice","k":"uno-sram-exhaustion-symptom","q":"String 객체와 긴 문자열을 남발한 Uno 스케치가 컴파일은 되지만 실행 중 갑자기 멈추거나 값이 이상해집니다. 가장 유력한 원인은?","ex":"SRAM이 모자라면 힙과 스택이 겹쳐 변수 값이 깨지거나 보드가 멈추는데 컴파일 단계에서는 잡히지 않습니다.\n💡 개념: 플래시 초과는 업로드 전에 오류로 막히므로 실행 중 이상 증상과는 다릅니다.\n🛠 실무: String 대신 고정 크기 char 배열을 쓰고 문자열 리터럴에 F()를 씌우는 것이 기본 처방입니다.","o":["플래시 32KB를 초과해 업로드가 잘린 것","SRAM 2KB가 부족해 스택과 힙이 충돌한 것","보율이 9600으로 고정되어 데이터가 밀린 것","PWM 핀이 아닌 곳에 analogWrite를 한 것"],"a":1},{"t":"choice","k":"uno-f-macro-purpose","q":"Serial.println(F(\"센서 초기화 완료\")) 처럼 F() 매크로를 쓰는 이유는?","ex":"F()가 없으면 문자열 리터럴이 프로그램 시작 시 SRAM으로 복사되지만 F()를 쓰면 플래시에 두고 필요할 때 읽습니다.\n💡 개념: 속도나 인코딩과는 무관하고 오직 메모리 배치의 문제입니다.\n🛠 실무: 디버그 문구가 많은 스케치에서 F()만 씌워도 수백 바이트의 SRAM을 되찾는 경우가 흔합니다.","o":["문자열을 자동으로 UTF-8로 변환해 주기 때문","출력 속도가 두 배 빨라지기 때문","문자열 리터럴을 플래시에 남겨 두어 SRAM 사용량을 줄이기 때문","시리얼 보율을 자동으로 맞춰 주기 때문"],"a":2}],"th":{"sum":"Arduino Uno는 UART, I2C, SPI 세 가지 통신을 지원하며 각각 선 개수, 속도, 장치 선택 방식이 다릅니다. 동시에 SRAM 2KB와 플래시 32KB라는 좁은 자원 안에서 전력까지 아껴야 합니다.","body":[{"h":"UART와 보율","t":"UART는 TX와 RX 두 선으로 데이터를 주고받는 비동기 통신이라 클럭선이 따로 없습니다. 대신 양쪽이 미리 같은 보율(baud rate)로 약속해야 하고, Serial.begin(9600)과 시리얼 모니터 설정이 다르면 화면에 깨진 문자가 쏟아집니다. Uno에서 하드웨어 시리얼은 디지털 0번(RX)과 1번(TX) 핀에 연결되어 있고 USB 업로드와 공유됩니다. 그래서 0번과 1번 핀에 장치를 연결한 채로 업로드하면 실패하기 쉽습니다."},{"h":"I2C는 2선 공유와 주소","t":"I2C는 SDA(데이터)와 SCL(클럭) 단 두 선을 여러 장치가 함께 씁니다. 마스터가 7비트 주소를 먼저 보내 그 주소를 가진 슬레이브 하나만 응답하게 만들어 장치를 구분합니다. 두 선 모두 풀업 저항이 필요하고 대개 4.7k옴 정도를 씁니다. 같은 주소를 가진 장치를 두 개 붙이면 충돌해서 둘 다 제대로 동작하지 않으므로 주소 점퍼를 바꾸거나 I2C 멀티플렉서를 씁니다. Uno의 I2C 핀은 A4(SDA)와 A5(SCL)입니다."},{"h":"SPI는 빠르지만 핀을 더 쓴다","t":"SPI는 MOSI, MISO, SCK 세 선을 모든 슬레이브가 공유하고, 슬레이브마다 별도의 CS(SS) 선을 하나씩 더 연결해 통신할 상대를 고릅니다. 주소 개념 없이 CS를 LOW로 내려 선택하므로 슬레이브가 늘면 핀도 그만큼 늘어납니다. 대신 클럭 속도가 높고 전이중이라 I2C보다 훨씬 빠릅니다. Uno에서는 11(MOSI), 12(MISO), 13(SCK), 10(기본 SS)이 SPI 핀입니다."},{"h":"전력과 메모리 제약","t":"배터리로 오래 동작해야 하면 avr/sleep.h의 슬립 모드로 CPU를 재우고 인터럽트나 워치독으로 깨우는 방식이 효과적입니다. Uno의 ATmega328P는 SRAM이 2KB뿐이라 문자열이나 배열을 많이 쓰면 금세 부족해지고 재부팅이나 이상 동작이 납니다. Serial.println(F(\"메시지\")) 처럼 F() 매크로로 문자열 리터럴을 32KB 플래시에 남겨 두면 RAM을 아낄 수 있습니다. 컴파일 후 출력되는 전역 변수 사용량 경고를 항상 확인하는 습관이 필요합니다."}],"code":{"c":"#include <Wire.h>\n#include <SPI.h>\n\nconst int CS_PIN = 10; // SPI 슬레이브별 CS\n\nvoid setup() {\n  Serial.begin(9600);          // 시리얼 모니터도 9600으로 맞출 것\n  Serial.println(F(\"boot ok\")); // F(): 문자열을 플래시에 두어 SRAM 절약\n\n  Wire.begin();                // I2C: A4=SDA, A5=SCL (풀업 필요)\n  Wire.beginTransmission(0x3C); // 7비트 주소로 슬레이브 지정\n  Wire.write(0x00);\n  Wire.endTransmission();\n\n  pinMode(CS_PIN, OUTPUT);\n  digitalWrite(CS_PIN, HIGH);  // 평소 비선택\n  SPI.begin();\n}\n\nvoid loop() {\n  digitalWrite(CS_PIN, LOW);   // 이 슬레이브만 선택\n  byte v = SPI.transfer(0x00);\n  digitalWrite(CS_PIN, HIGH);\n  Serial.println(v);\n  delay(1000);\n}","cap":"I2C는 7비트 주소로, SPI는 CS 핀으로 상대를 고르며 F() 매크로로 SRAM을 아낍니다."},"key":["UART는 클럭선 없이 비동기라 양쪽 보율이 다르면 깨진 문자가 나온다","I2C는 SDA/SCL 2선을 공유하고 7비트 주소로 슬레이브를 구분하며 풀업 저항이 필요하다","SPI는 MOSI/MISO/SCK 공유에 슬레이브마다 CS가 필요해 빠르지만 핀을 더 쓴다","Uno는 SRAM 2KB·플래시 32KB이며 F() 매크로로 문자열을 플래시에 두면 RAM을 절약한다"]}},{"t":"직접 이어 보기 — I2C 와 UART","th":{"sum":"I2C 는 두 가닥(SDA·SCL)으로 여러 장치를 잇는다. UART 는 두 가닥이지만 **서로 엇갈려** 이어야 한다.","body":[{"h":"I2C 는 같은 이름끼리","t":"SDA 는 SDA 로, SCL 은 SCL 로 잇는다. Uno 에서는 A4 가 SDA, A5 가 SCL 이다. 여러 장치를 같은 두 가닥에 나란히 붙일 수 있고, 주소로 구분한다. 접지(GND)를 공유하지 않으면 통신이 되지 않는다."},{"h":"UART 는 엇갈려서","t":"내 TX(보내기)는 상대의 RX(받기)로, 내 RX 는 상대의 TX 로 간다. TX 를 TX 에 이으면 둘 다 말만 하고 아무도 듣지 않는다. 이것도 GND 를 공유해야 기준 전압이 맞는다."}],"code":{"c":"// I2C:  SDA↔SDA, SCL↔SCL, GND 공유\n// UART: TX→RX, RX→TX, GND 공유","cap":"I2C 는 같은 이름, UART 는 엇갈려서"},"key":["I2C 는 SDA·SCL 같은 이름끼리","UART 는 TX↔RX 로 엇갈리게","어느 쪽이든 GND 를 공유한다"]},"q":[{"k":"I2C 디스플레이 잇기","cat":"internals","q":"I2C 디스플레이를 이으세요. Uno 의 <b>A4 가 SDA, A5 가 SCL</b> 입니다. 전원과 접지도 함께 이어야 합니다.","ex":"I2C 는 같은 이름끼리 잇습니다 — SDA 를 SCL 에 물리면 통신이 되지 않아요. 그리고 두 장치가 GND 를 공유해야 신호의 기준이 맞습니다. 공유하지 않으면 값이 제멋대로 들어옵니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["A4","A5","5V","GND"]},{"id":"oled","label":"I2C 디스플레이","pins":["VCC","GND","SDA","SCL"]}],"checks":[{"d":"SDA 끼리 이어진다 (A4)","link":["oled.SDA","uno.A4"]},{"d":"SCL 끼리 이어진다 (A5)","link":["oled.SCL","uno.A5"]},{"d":"VCC 가 5V 에 붙는다","link":["oled.VCC","uno.5V"]},{"d":"접지를 공유한다","link":["oled.GND","uno.GND"]},{"d":"SDA 와 SCL 이 서로 붙어 있지 않다","apart":["oled.SDA","oled.SCL"],"wires":true}],"start":[],"sol":[["oled.SDA","uno.A4"],["oled.SCL","uno.A5"],["oled.VCC","uno.5V"],["oled.GND","uno.GND"]]},{"k":"UART 를 엇갈려 잇기","cat":"internals","q":"블루투스 모듈을 UART 로 이으세요. <b>TX 는 RX 로, RX 는 TX 로</b> 엇갈려야 합니다. 접지도 공유합니다.","ex":"TX 를 TX 에, RX 를 RX 에 물려 놓았습니다. 둘 다 말만 하고 아무도 듣지 않아 한 글자도 오가지 않아요. 먼저 두 선을 지우고 엇갈려 다시 이으세요.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["TX","RX","5V","GND"]},{"id":"bt","label":"블루투스 모듈","pins":["VCC","GND","TX","RX"]}],"checks":[{"d":"모듈의 TX 가 보드의 RX 로 간다","link":["bt.TX","uno.RX"]},{"d":"모듈의 RX 가 보드의 TX 로 간다","link":["bt.RX","uno.TX"]},{"d":"TX 끼리 붙어 있지 않다","apart":["bt.TX","uno.TX"],"wires":true},{"d":"VCC 가 5V 에 붙는다","link":["bt.VCC","uno.5V"]},{"d":"접지를 공유한다","link":["bt.GND","uno.GND"]}],"start":[["bt.TX","uno.TX"],["bt.RX","uno.RX"]],"sol":[["bt.TX","uno.RX"],["bt.RX","uno.TX"],["bt.VCC","uno.5V"],["bt.GND","uno.GND"]]}]}]},{"t":"실행형 실전 — 신호를 길들인다","l":[{"t":"디바운스·값 매핑·이동평균","xp":80,"th":{"sum":"하드웨어의 신호는 더럽다 — **튀고(채터링), 어긋나고(범위), 흔들린다(노이즈)**. 셋 다 몇 줄의 필터로 길들일 수 있다.","body":[{"h":"믿을 때까지 기다린다","t":"기계식 버튼은 누르는 순간 수 ms 동안 붙었다 떨어졌다를 반복한다. 디바운스는 '같은 값이 충분히 유지될 때만 믿는다' — 값이 흔들리면 **대기 시간을 리셋**하는 것이 핵심이다. delay() 로 기다리면 다른 일이 전부 멈추므로, 시각을 인자로 받는 비차단 구조라야 한다."},{"h":"범위를 옮기고 노이즈를 눌러 담는다","t":"10비트 ADC 를 8비트 PWM 으로 옮길 때는 **곱셈 먼저, 나눗셈 나중** — 정수 나눗셈이 먼저 오면 거의 항상 0이 된다. 내장 map() 은 범위 밖 입력을 자르지 않으므로 clamp 를 함께 쓴다. 이동평균 링 버퍼는 **차기 전에는 받은 개수로** 나눠야 초반 값이 왜곡되지 않는다."}],"code":{"c":"// 흔들리면 대기 시간을 다시 시작\nif (reading !== cand) { cand = reading; since = now; }\nif (cand !== stable && now - since >= ms) stable = cand;","cap":"리셋 없는 디바운스는 채터링 중간에 확정해 버린다"},"key":["디바운스는 유지 시간 + 리셋","비차단 구조라야 루프가 계속 돈다","정수 연산은 곱셈 먼저","이동평균 분모는 min(받은 개수, n)"]},"q":[{"t":"code","run":"js","k":"버튼 디바운스","cat":"internals","q":"기계식 버튼의 <b>디바운스</b>를 구현하세요. <code>makeDebounce(ms)</code> 는 <code>(reading, now)</code> 를 받는 함수를 돌려줍니다. 새 읽기값이 <b><code>ms</code> 밀리초 동안 유지될 때만</b> 안정값을 그 값으로 바꾸고, 항상 현재 안정값을 돌려줍니다. 읽기값이 흔들리면 대기 시간은 <b>다시 시작</b>됩니다. 초기 안정값은 0 입니다.","src":"function makeDebounce(ms) {\n  // TODO: 후보가 ms 동안 유지되면 안정값 갱신\n  return (reading, now) => reading;\n}","sol":"function makeDebounce(ms) {\n  let stable = 0, cand = 0, since = 0;\n  return (reading, now) => {\n    if (reading !== cand) { cand = reading; since = now; }\n    if (cand !== stable && now - since >= ms) stable = cand;\n    return stable;\n  };\n}","tests":[{"in":"(() => { const d=makeDebounce(50); return [d(1,0), d(1,30), d(1,50)]; })()","out":"[0,0,1]"},{"in":"(() => { const d=makeDebounce(50); d(1,0); d(0,20); d(1,40); return d(1,100); })()","out":"1"},{"in":"(() => { const d=makeDebounce(50); d(1,0); d(0,20); return d(1,60); })()","out":"0"},{"in":"(() => { const d=makeDebounce(50); d(1,0); d(1,50); d(0,60); return [d(0,100), d(0,110)]; })()","out":"[1,0]"}],"edge":[{"in":"(() => { const d=makeDebounce(0); return d(1,5); })()","out":"1"},{"in":"(() => { const d=makeDebounce(50); return [d(0,0), d(0,100)]; })()","out":"[0,0]"}],"ex":"🎯 기계식 접점은 누르는 순간 수 밀리초 동안 <b>붙었다 떨어졌다를 반복</b>합니다(채터링). 그대로 읽으면 한 번 눌렀는데 인터럽트가 수십 번 발생합니다 — 카운터가 몇 씩 뛰는 고전적 증상입니다.\n💡 해법은 '<b>같은 값이 충분히 오래 유지될 때만 믿는다</b>' 입니다. 값이 흔들리면 <code>since</code> 를 지금으로 리셋해 대기 시간을 다시 시작하는 것이 핵심입니다 — 리셋 없이 첫 변화 시각만 기억하면 채터링 중간에 잘못 확정됩니다.\n⚠️ <code>delay(50)</code> 으로 기다리는 방식은 그동안 <b>다른 입력·통신이 전부 멈춥니다</b>. 시각을 인자로 받는 이 구조(비차단)라야 루프가 계속 돌 수 있고, 테스트도 가능해집니다.\n🔧 같은 패턴이 소프트웨어에도 그대로 있습니다 — 검색창의 디바운스, 알림 묶어 보내기, 헬스체크의 연속 N회 실패 조건이 모두 '흔들림을 걸러 안정 신호만 통과' 시키는 같은 필터입니다."},{"t":"code","run":"js","k":"아날로그 값 매핑","cat":"internals","q":"센서 값을 다른 범위로 <b>매핑</b>하세요. <code>mapRange(x, inLo, inHi, outLo, outHi)</code> 는 <code>x</code> 를 입력 범위에서 출력 범위로 비례 변환합니다. <b>입력 범위를 벗어나면 잘라내고(clamp)</b>, 결과는 <b>내림(floor)</b>으로 정수화합니다. 출력 범위는 뒤집혀 있을 수도 있습니다.","src":"function mapRange(x, inLo, inHi, outLo, outHi) {\n  // TODO: clamp 후 비례 변환, floor\n  return x;\n}","sol":"function mapRange(x, inLo, inHi, outLo, outHi) {\n  const cx = Math.min(Math.max(x, inLo), inHi);\n  return Math.floor((cx - inLo) * (outHi - outLo) / (inHi - inLo) + outLo);\n}","tests":[{"in":"mapRange(512,0,1023,0,255)","out":"127"},{"in":"mapRange(0,0,1023,0,255)","out":"0"},{"in":"mapRange(1023,0,1023,0,255)","out":"255"},{"in":"mapRange(2000,0,1023,0,255)","out":"255"}],"edge":[{"in":"mapRange(-5,0,1023,0,255)","out":"0"},{"in":"mapRange(5,0,10,100,0)","out":"50"}],"ex":"🎯 10비트 ADC(0~1023)를 8비트 PWM(0~255)으로 옮기는 것이 아두이노의 가장 흔한 계산입니다. 공식은 '<b>입력에서의 비율을 출력 범위에 다시 펼치기</b>' — <code>(x−inLo)·(outHi−outLo)/(inHi−inLo)+outLo</code> 입니다.\n💡 <b>곱셈을 먼저, 나눗셈을 나중에</b> 해야 정수 연산에서 정밀도를 잃지 않습니다. <code>x/1023*255</code> 를 정수로 계산하면 <code>x/1023</code> 이 거의 항상 0이 됩니다 — C 정수 나눗셈의 고전적 함정입니다.\n⚠️ 아두이노의 내장 <code>map()</code> 은 <b>범위를 벗어난 입력을 자르지 않습니다</b>. 센서 스파이크가 그대로 출력 범위 밖으로 나가 서보를 한계 밖으로 밀 수 있어, 실전에서는 <code>constrain()</code> 을 함께 쓰는 것이 정석입니다.\n🔧 출력 범위를 <code>(100, 0)</code> 처럼 뒤집으면 <b>반전 매핑</b>이 공짜로 됩니다 — 밝을수록 LED 를 어둡게 하는 조도 반응이 한 줄로 끝납니다."},{"t":"code","run":"js","k":"링 버퍼 이동평균","cat":"internals","q":"노이즈 낀 센서 값을 <b>이동평균</b>으로 부드럽게 만드세요. <code>makeAvg(n)</code> 은 값을 하나 받을 때마다 <b>최근 n개의 평균</b>을 돌려주는 함수를 만듭니다. 링 버퍼로 구현하고, <b>버퍼가 차기 전에는 지금까지 받은 개수로</b> 나눠야 합니다.","src":"function makeAvg(n) {\n  const buf = [];\n  return (v) => {\n    buf.push(v);\n    return buf.reduce((a, b) => a + b, 0) / n;\n  };\n}","sol":"function makeAvg(n) {\n  const buf = new Array(n).fill(0);\n  let idx = 0, count = 0, sum = 0;\n  return (v) => {\n    if (count === n) sum -= buf[idx];\n    else count++;\n    buf[idx] = v; sum += v;\n    idx = (idx + 1) % n;\n    return sum / count;\n  };\n}","tests":[{"in":"(() => { const a=makeAvg(3); return [a(3), a(6), a(9), a(12)]; })()","out":"[3,4.5,6,9]"},{"in":"(() => { const a=makeAvg(2); a(10); a(20); return a(30); })()","out":"25"},{"in":"(() => { const a=makeAvg(4); return a(8); })()","out":"8"},{"in":"(() => { const a=makeAvg(3); a(10); a(10); return a(100); })()","out":"40"}],"edge":[{"in":"(() => { const a=makeAvg(1); a(5); return a(9); })()","out":"9"},{"in":"(() => { const a=makeAvg(2); a(1); return a(2); })()","out":"1.5"}],"ex":"🎯 시작 코드의 버그는 <b>분모</b>입니다. 버퍼가 차기 전에 n 으로 나누면 첫 값들이 실제보다 작게 나옵니다 — 전원을 켠 직후 몇 초간 센서가 '낮게' 읽히는 미스터리의 정체가 대개 이것입니다.\n💡 링 버퍼는 <b>메모리가 고정</b>이고, 합계를 증분으로 유지하면(나갈 값 빼고 들어올 값 더하기) 매번 전체를 다시 더하지 않아 <b>O(1)</b> 입니다. 마이크로컨트롤러의 2KB RAM 에서는 이 차이가 생존의 문제입니다.\n⚠️ 창 크기 n 은 트레이드오프입니다 — 크면 부드럽지만 <b>반응이 느려지고</b>, 작으면 빠르지만 노이즈가 남습니다. 스파이크 노이즈(순간 튐)에는 평균보다 <b>중앙값 필터</b>가 훨씬 강합니다.\n🔧 같은 원리가 서버 모니터링의 이동평균 그래프, 주가의 MA 선, 지수이동평균(EMA, 버퍼 없이 <code>avg += α(v−avg)</code>)으로 이어집니다."}]}]}]);
